function shell(body,client=false){let unread=notificationUnread().length;R.innerHTML=`<div class="shell ${client?'clientmode':''}"><aside class="side"><div class="logo">C<span>O</span>LAB</div><nav class="nav">${nav(client?clientNav():teamNav())}</nav><div class="foot">${E(S.user?.email||'')}<br><button id="out" class="btn ghost small" style="margin-top:9px">Sair</button></div></aside><main class="main"><header class="top"><div><small class="ey">${client?'PORTAL DO CLIENTE':'COLAB OPERACIONAL'}</small><h1>${title()}</h1></div><div class="topactions">${!client?`<button id="bell" class="bell ${unread?'has-unread':''}" aria-label="Notificações"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9"/><path d="M10 21h4"/></svg>${unread?`<span id="bellBadge" class="bellbadge">${unread>99?'99+':unread}</span>`:''}</button>`:''}<button id="ref" class="btn ghost small">↻</button></div></header>${!client&&['finance','goals'].includes(V)?revenueMilestoneBar():''}${body}</main></div>${!client?chatDock():''}${modal()}`;document.querySelectorAll('[data-v]').forEach(b=>b.onclick=()=>{V=b.dataset.v;render()});document.getElementById('out').onclick=()=>{clear();auth()};document.getElementById('ref').onclick=async()=>{await load();render();toast('Atualizado')};document.getElementById('bell')?.addEventListener('click',openNotifications);bind();setTimeout(hydratePreviews,50)}
function render(){M.role==='team'?team():clientPortal()}
function team(){let b=V==='agenda'?agendaPage():V==='clients'?clientsPage():V==='commercial'?commercialPage():V==='dna'?dnaPage():V==='mural'?muralPage():V==='tasks'?tasksPage():V==='content'?contentPage():V==='ideas'?ideasPage():V==='production'?productionPage():V==='finance'?financePage():V==='goals'?goalsPage():V==='more'?morePage():V==='library'?libraryPage():V==='traffic'?trafficPage():V==='identityTeam'?identityTeamPage():V==='files'?filesPage(false):V==='access'?accessPage():homePage();shell(b)}
function greeting(){let h=new Date().getHours();return h<12?'Bom dia':h<18?'Boa tarde':'Boa noite'}
function dailyWord(){let a=[['Tudo tem o seu tempo determinado.','Eclesiastes 3:1'],['Consagre ao Senhor tudo o que você faz.','Provérbios 16:3'],['Seja forte e corajosa.','Josué 1:9'],['Alegrai-vos na esperança e sede pacientes na tribulação.','Romanos 12:12'],['Deus é quem fortalece o caminho.','Salmos 18:32'],['Confia no Senhor de todo o teu coração.','Provérbios 3:5'],['A fé também é continuar antes de enxergar o resultado.','Reflexão Colab'],['O trabalho constante constrói aquilo que a pressa não sustenta.','Reflexão Colab'],['Faça o que está nas suas mãos hoje. O restante se constrói no caminho.','Reflexão Colab'],['Gratidão pelo que já chegou. Coragem para o que ainda está sendo construído.','Reflexão Colab'],['Que propósito e excelência caminhem juntos hoje.','Reflexão Colab'],['Pequenos passos também fazem parte de grandes promessas.','Reflexão Colab']];let d=new Date(),k=d.getFullYear()*372+(d.getMonth()+1)*31+d.getDate(),x=a[k%a.length];return`<div class="daily-word"><small>PARA HOJE</small><strong>${E(x[0])}</strong><span>${E(x[1])}</span></div>`}
function homeRadarModal(kind){let td=today(),title='',subtitle='',rows='',action='tasks';if(kind==='overdue'){let a=D.tasks.filter(x=>x.status!=='done'&&x.due_date&&x.due_date<td);title='Demandas atrasadas';subtitle=a.length?'Estas são as demandas que já passaram do prazo.':'Nenhuma demanda atrasada por aqui.';rows=a.map(t=>`<button class="radar-detail-row" data-taskopen="${t.id}"><span>${E(cl(t.client_id)?.name||'Colab · Interno')} · ${E(lab(t.service))}</span><b>${E(t.title)}</b><small>${E(profile(t.assigned_to)?.display_name||'Sem responsável')} · prazo ${fmtDate(t.due_date)}</small><em>${E(ts(t.status))}</em></button>`).join('')}else if(kind==='doing'){let a=D.tasks.filter(x=>x.status==='doing');title='Em execução';subtitle=a.length?'O que a equipe está tocando agora.':'Nenhuma demanda em execução agora.';rows=a.map(t=>`<button class="radar-detail-row" data-taskopen="${t.id}"><span>${E(cl(t.client_id)?.name||'Colab · Interno')} · ${E(lab(t.service))}</span><b>${E(t.title)}</b><small>${E(profile(t.assigned_to)?.display_name||'Sem responsável')}${t.due_date?' · prazo '+fmtDate(t.due_date):''}</small><em>Em andamento</em></button>`).join('')}else if(kind==='pending'){let a=(D.approvals||[]).filter(x=>x.status==='pending').map(x=>D.contents.find(c=>c.id===x.content_id)||x.contents).filter(Boolean);title='Aguardando cliente';subtitle=a.length?'Conteúdos que estão esperando aprovação do cliente.':'Nenhum conteúdo aguardando aprovação.';action='content';rows=a.map(c=>`<button class="radar-detail-row" data-contentopen="${c.id}"><span>${E(cl(c.client_id)?.name||'Cliente')} · ${E(fmt(c.format))}</span><b>${E(c.title)}</b><small>${fmtDate(c.publication_date)} · ${E(pillar(c.editorial_pillar_id)?.name||'Sem linha editorial')}</small><em>Aguardando aprovação</em></button>`).join('')}else{let cc=D.contents.filter(x=>x.publication_date===td),ev=D.events.filter(x=>String(x.starts_at||'').slice(0,10)===td);title='Hoje';subtitle=(cc.length||ev.length)?'Tudo que está previsto para hoje em um só lugar.':'Nada previsto para hoje.';action='agenda';rows=cc.map(c=>`<button class="radar-detail-row" data-contentopen="${c.id}"><span>CONTEÚDO · ${E(cl(c.client_id)?.name||'Cliente')}</span><b>${E(c.title)}</b><small>${E(fmt(c.format))} · ${E(cs(c.status))}</small><em>Hoje</em></button>`).join('')+ev.map(e=>`<button class="radar-detail-row" data-eventopen="${e.id}"><span>COMPROMISSO · ${E(cl(e.client_id)?.name||'')}</span><b>${E(e.title)}</b><small>${fmtTime(e.starts_at)} · ${E(lab(e.event_type))}${e.location?' · '+E(e.location):''}</small><em>Hoje</em></button>`).join('')}return`<div class="modalbg"><div class="modal wide radar-modal"><div class="head"><div><small class="ey">RADAR COLAB</small><h2>${E(title)}</h2><p class="muted">${E(subtitle)}</p></div><button class="btn ghost small" data-close>×</button></div><div class="radar-detail-list">${rows||'<div class="empty">Tudo certo por aqui. ✨</div>'}</div><button class="btn ghost full radar-open-all" data-radarall="${action}">${action==='tasks'?'Abrir Demandas':action==='content'?'Abrir Conteúdos':'Abrir Agenda'} →</button></div></div>`}
function homePage(){let td=today(),open=D.tasks.filter(x=>x.status!=='done'),overdueTasks=open.filter(x=>x.due_date&&x.due_date<td),doing=open.filter(x=>x.status==='doing'),todayContent=D.contents.filter(x=>x.publication_date===td),todayEvents=D.events.filter(x=>String(x.starts_at||'').slice(0,10)===td),pending=D.approvals.filter(a=>a.status==='pending'),changes=D.contents.filter(c=>c.status==='changes_requested'),unassigned=open.filter(x=>!x.assigned_to),commercialFollow=(D.opportunities||[]).filter(x=>!['won','lost'].includes(x.stage)&&x.next_action_date&&x.next_action_date<=td),lateReceivables=D.receivables.filter(r=>r.status==='pending'&&r.due_date<td),renewals=D.contracts.filter(c=>c.status==='active'&&daysBetween(td,c.end_date)<=30),dueCosts=(D.recurringCosts||[]).filter(x=>x.status==='active'&&daysBetween(td,x.next_due_date)<=3),upcoming=D.events.filter(e=>e.starts_at&&String(e.starts_at).slice(0,10)>=td).slice().sort((a,b)=>String(a.starts_at).localeCompare(String(b.starts_at))).slice(0,5),team=D.profiles||[],muralNotes=(D.muralNotes||[]).filter(x=>!x.resolved&&x.author_id!==S.user?.id&&(!x.recipient_id||x.recipient_id===S.user?.id)).slice(0,3);let ownerCards=team.map(p=>{let mine=open.filter(t=>t.assigned_to===p.user_id),exec=mine.filter(t=>t.status==='doing'),late=mine.filter(t=>t.due_date&&t.due_date<td);return`<article class="team-now-card ${exec.length?'active':''}"><div class="head"><div><small class="ey">EQUIPE</small><h3>${E(p.display_name)}</h3></div><span class="team-now-dot ${exec.length?'on':''}"></span></div><div class="team-count"><b>${mine.length}</b><span>demandas pendentes</span></div><div class="chips"><span class="tag ${exec.length?'o':''}">${exec.length} em andamento</span>${late.length?`<span class="tag r">${late.length} atrasada${late.length>1?'s':''}</span>`:''}</div>${exec.length?`<div class="team-live"><small>EM EXECUÇÃO AGORA</small>${exec.slice(0,3).map(t=>`<button data-taskopen="${t.id}"><span class="live-dot"></span><b>${E(t.title)}</b><em>${E(cl(t.client_id)?.name||'Interno')}</em></button>`).join('')}</div>`:'<div class="team-idle">Nenhuma demanda em execução agora.</div>'}</article>`}).join('');let reminders=[...lateReceivables.slice(0,4).map(r=>`<div class="row"><span class="dot r"></span><div class="grow"><b>${E(cl(r.client_id)?.name||'Cliente')} · mensalidade em atraso</b><small>Venceu ${fmtDate(r.due_date)} · ${money(r.amount)}</small></div><span class="tag r">Cobrar</span></div>`),...renewals.slice(0,4).map(c=>{let d=daysBetween(td,c.end_date);return`<div class="row"><span class="dot ${d<=7?'r':'y'}"></span><div class="grow"><b>${E(cl(c.client_id)?.name||'Cliente')} · renovação de contrato</b><small>${d<0?'Contrato vencido em '+fmtDate(c.end_date):'Termina em '+d+' dias · '+fmtDate(c.end_date)}</small></div><span class="tag ${d<=7?'r':'y'}">${d<0?'Vencido':d<=7?'Urgente':d<=15?'Atenção':'Renovar'}</span></div>`}),...dueCosts.slice(0,4).map(x=>{let d=daysBetween(td,x.next_due_date);return`<div class="row"><span class="dot ${d<0?'r':'y'}"></span><div class="grow"><b>${E(x.name)} · ${money(x.amount)}</b><small>${d<0?'Venceu '+fmtDate(x.next_due_date):d===0?'Vence hoje':d===1?'Vence amanhã':'Vence em '+d+' dias'} · ${E(profile(x.responsible_to)?.display_name||'Equipe')}</small></div><span class="tag ${d<0?'r':'y'}">${d<0?'Atrasada':'Pagar'}</span></div>`}),...overdueTasks.slice(0,5).map(t=>`<div class="row" data-taskopen="${t.id}"><span class="dot r"></span><div class="grow"><b>${E(t.title)}</b><small>${E(cl(t.client_id)?.name||'Interno')} · ${E(profile(t.assigned_to)?.display_name||'Sem responsável')} · venceu ${fmtDate(t.due_date)}</small></div><span class="tag r">Atrasada</span></div>`),...changes.slice(0,4).map(c=>`<div class="row" data-contentopen="${c.id}"><span class="dot y"></span><div class="grow"><b>${E(c.title)}</b><small>${E(cl(c.client_id)?.name||'')} · cliente pediu alteração</small></div><span class="tag y">Revisar</span></div>`),...unassigned.slice(0,3).map(t=>`<div class="row" data-taskopen="${t.id}"><span class="dot y"></span><div class="grow"><b>${E(t.title)}</b><small>${E(cl(t.client_id)?.name||'Interno')} · ainda sem responsável</small></div><span class="tag y">Definir</span></div>`),...commercialFollow.slice(0,4).map(o=>`<div class="row"><span class="dot o"></span><div class="grow"><b>${E(o.name)} · follow-up comercial</b><small>${E(o.next_action||'Retomar contato')}${o.next_action_date?' · '+fmtDate(o.next_action_date):''} · ${E(profile(o.owner_id)?.display_name||'Equipe')}</small></div><button class="btn ghost small" data-go="commercial">Abrir</button></div>`)];return`<section class="hero office-hero"><div><small class="ey">${new Date().toLocaleDateString('pt-BR',{weekday:'long',day:'2-digit',month:'long'}).toUpperCase()}</small><h2>${greeting()}, ${E(profile(S.user?.id)?.display_name||'COLAB')}.</h2><div class="mode-on">Modo Colab: <b>ON</b><span class="mode-dot" aria-hidden="true"></span></div>${dailyWord()}</div><div class="quick"><button class="btn pri" data-m="taskNew"><span class="quickplus">＋</span><span>Demanda</span></button><button class="btn ghost" data-m="contentNew"><span class="quickplus">＋</span><span>Conteúdo</span></button><button class="btn ghost" data-m="storyEventNew"><span class="quickplus">＋</span><span>Evento</span></button></div></section><section class="office-radar"><div class="head"><div><small class="ey">RADAR COLAB</small><h3>O que merece atenção agora</h3></div></div><div class="stats"><article class="stat ${overdueTasks.length?'attention':''}" data-homeradar="overdue"><span>Demandas atrasadas</span><b>${overdueTasks.length}</b><small>${overdueTasks.length?'precisam de ação':'nenhum atraso'}</small></article><article class="stat" data-homeradar="doing"><span>Em execução</span><b>${doing.length}</b><small>pela equipe agora</small></article><article class="stat" data-homeradar="pending"><span>Aguardando cliente</span><b>${pending.length}</b><small>conteúdos para aprovação</small></article><article class="stat" data-homeradar="today"><span>Hoje</span><b>${todayContent.length+todayEvents.length}</b><small>${todayContent.length} conteúdos · ${todayEvents.length} compromissos</small></article></div></section><section class="panel office-team"><div class="head"><div><small class="ey">EQUIPE AGORA</small><h3>Distribuição de demandas</h3></div><button class="btn ghost small" data-go="tasks">Ver demandas</button></div><div class="office-team-grid">${ownerCards||'<div class="empty">Nenhuma pessoa cadastrada na equipe.</div>'}</div></section>${muralNotes.length?`<section class="panel mural-preview mural-preview-alert"><div class="head"><div><small class="ey">TEM RECADO PRA VOCÊ 👀</small><h3>${E(profile(muralNotes[0].author_id)?.display_name||'Alguém da equipe')} deixou um post-it no Mural</h3></div><button class="btn ghost small" data-go="mural">Ver no Mural →</button></div>${muralNotes.map(n=>`<div class="mural-preview-note"><span>${E(n.emoji||'🧡')}</span><div class="grow"><b>${E(n.body)}</b><small>${E(profile(n.author_id)?.display_name||'Equipe')}${n.recipient_id?' → '+E(profile(n.recipient_id)?.display_name||'Equipe'):''}</small></div></div>`).join('')}</section>`:''}<div class="grid2 office-bottom"><section class="panel"><div class="head"><div><small class="ey">LEMBRETES IMPORTANTES</small><h3>Não deixar passar</h3></div></div>${reminders.join('')||'<div class="empty">Nada urgente por aqui. ✨</div>'}</section><section class="panel"><div class="head"><div><small class="ey">PRÓXIMOS</small><h3>AGENDA</h3></div><button class="btn ghost small" data-go="agenda">Abrir agenda</button></div>${upcoming.map(eventRow).join('')||'<div class="empty">Nenhum compromisso próximo.</div>'}</section></div>`}
function taskRow(t){return`<div class="row" data-taskopen="${t.id}"><span class="dot ${t.priority==='urgent'?'r':''}"></span><div class="grow"><b>${E(t.title)}</b><small>${E(cl(t.client_id)?.name||'Interno')} · ${E(profile(t.assigned_to)?.display_name||'Sem responsável')}</small></div><span class="tag">${E(ts(t.status))}</span></div>`}
function eventRow(e){return`<div class="row" ${M?.role==='team'?`data-eventopen="${e.id}"`:''}><div class="avatar">${String(e.starts_at||'').slice(8,10)||'—'}</div><div class="grow"><b>${E(e.title)}</b><small>${e.client_id?E(cl(e.client_id)?.name||'')+' · ':''}${fmtTime(e.starts_at)} ${e.contracted_hours?'· '+e.contracted_hours+'h':''}</small></div><span class="tag b">${E(lab(e.event_type))}</span></div>`}
function sum(a,k){return a.reduce((s,x)=>s+Number(x[k]||0),0)}function daysBetween(a,b){if(!a||!b)return 999;return Math.ceil((new Date(b+'T12:00:00')-new Date(a+'T12:00:00'))/86400000)}
function agendaItems(){let items=[];D.tasks.forEach(x=>x.due_date&&items.push({date:x.due_date,type:'task',client:x.client_id,title:x.title,meta:profile(x.assigned_to)?.display_name||'Demanda',id:x.id}));D.contents.forEach(x=>x.publication_date&&items.push({date:x.publication_date,type:'content',client:x.client_id,title:x.title,meta:fmt(x.format),id:x.id}));D.events.forEach(x=>x.starts_at&&items.push({date:String(x.starts_at).slice(0,10),type:'event',client:x.client_id,title:x.title,meta:lab(x.event_type),id:x.id}));D.receivables.forEach(x=>x.due_date&&x.status!=='paid'&&Number(x.amount||0)>0&&items.push({date:x.due_date,type:'money',client:x.client_id,title:'Receber '+money(x.amount),meta:x.description,id:x.id}));D.contracts.forEach(x=>x.end_date&&x.status==='active'&&items.push({date:x.end_date,type:'contract',client:x.client_id,title:'Fim do contrato',meta:'Renovação',id:x.id}));(D.recurringCosts||[]).filter(x=>x.status==='active').forEach(x=>x.next_due_date&&items.push({date:x.next_due_date,type:'bill',client:null,title:'Pagar '+x.name,meta:money(x.amount),id:x.id}));return items}
function agendaPage(){let items=agendaItems().filter(x=>dateMonth(x.date)===agendaMonth).filter(x=>agendaClient==='all'||x.client===agendaClient).filter(x=>agendaType==='all'||x.type===agendaType);return`<div class="toolbar"><div><p class="muted">Agenda geral da agência: conteúdo, prazos, eventos, cobranças e renovações.</p></div><button class="btn pri" data-m="eventNew">＋ Compromisso</button></div><div class="filters"><input id="agendaMonth" type="month" value="${agendaMonth}"><select id="agendaClient"><option value="all">Todos os clientes</option>${D.clients.map(c=>`<option value="${c.id}" ${agendaClient===c.id?'selected':''}>${E(c.name)}</option>`).join('')}</select><select id="agendaType"><option value="all">Tudo</option><option value="task" ${agendaType==='task'?'selected':''}>Demandas</option><option value="content" ${agendaType==='content'?'selected':''}>Conteúdo</option><option value="event" ${agendaType==='event'?'selected':''}>Eventos/Gravações</option><option value="money" ${agendaType==='money'?'selected':''}>Financeiro</option><option value="contract" ${agendaType==='contract'?'selected':''}>Contratos</option><option value="bill" ${agendaType==='bill'?'selected':''}>Contas/Assinaturas</option></select></div><div class="calendar-legend" aria-label="Legenda do calendário"><strong>CORES DA AGENDA</strong><span><i class="content"></i>Conteúdo</span><span><i class="legend-task"></i>Demanda</span><span><i class="event"></i>Evento / captação</span><span><i class="receive"></i>A receber</span><span><i class="contract"></i>Contrato / renovação</span><span><i class="bill"></i>Conta / assinatura</span></div><section class="panel">${calendarGrid(agendaMonth,items,true)}</section>`}
function calendarGrid(month,items,teamAgenda=false){let [y,m]=month.split('-').map(Number),first=new Date(y,m-1,1),days=new Date(y,m,0).getDate(),offset=(first.getDay()+6)%7,cells=[];for(let i=0;i<offset;i++)cells.push('<div class="day dim"></div>');for(let n=1;n<=days;n++){let d=`${month}-${String(n).padStart(2,'0')}`,it=items.filter(x=>x.date===d);cells.push(`<div class="day"><b>${n}</b>${it.map(x=>`<span class="calitem ${x.type==='content'&&x.status?'content-'+x.status:x.type==='event'?'event':x.type==='task'?'taskc':x.type==='money'?'money':x.type==='bill'?'bill':x.type==='contract'?'contract':''}" ${x.type==='content'?`data-contentopen="${x.id}"`:x.type==='task'?`data-taskopen="${x.id}"`:x.type==='event'&&teamAgenda?`data-eventopen="${x.id}"`:x.type==='money'&&teamAgenda?`data-receivableopen="${x.id}"`:''}><strong>${E(x.title)}</strong><br>${x.client?E(cl(x.client)?.name||'')+' · ':''}${E(x.meta||'')}</span>`).join('')}</div>`)}return`<div class="calendar">${['SEG','TER','QUA','QUI','SEX','SÁB','DOM'].map(x=>`<div class="weekday">${x}</div>`).join('')}${cells.join('')}</div>`}
function clientsPage(){return`<div class="toolbar"><p class="muted">Plano ativo, operação, objetivos e histórico de cada cliente.</p><button class="btn pri" data-m="clientNew">＋ Novo cliente</button></div><div class="clients">${D.clients.map(c=>{let co=D.contracts.find(x=>x.client_id===c.id&&x.status==='active'),open=D.receivables.filter(r=>r.client_id===c.id&&r.status==='pending'),sv=D.services.filter(s=>s.client_id===c.id&&s.active);return`<article class="client-card ${c.active?'':'archived'}" data-clientopen="${c.id}"><div class="head"><div class="avatar">${E(c.initials||ini(c.name))}</div><span class="tag ${c.active?'g':''}">${c.active?'Ativo':'Inativo'}</span></div><h3>${E(c.name)}</h3><p class="muted">${E(c.segment||'Cliente Colab')}</p><div class="services">${sv.map(s=>`<span class="tag">${E(lab(s.service))}</span>`).join('')}</div><div class="splitline"></div><small class="muted">${co?`${money(co.monthly_fee)}/mês · até ${fmtDate(co.end_date)}`:'Sem Plano Ativo'}</small></article>`}).join('')}</div>`}

function tasksPage(){let cols=[['todo','A fazer'],['doing','Em andamento'],['approval','Aprovação'],['done','Concluído']],filtered=D.tasks.filter(t=>(taskClientFilter==='all'||t.client_id===taskClientFilter)&&(taskOwnerFilter==='all'||(taskOwnerFilter==='none'?!t.assigned_to:t.assigned_to===taskOwnerFilter))&&(taskServiceFilter==='all'||t.service===taskServiceFilter)),dirty=taskClientFilter!=='all'||taskOwnerFilter!=='all'||taskServiceFilter!=='all';return`<div class="toolbar"><p class="muted">Demandas com cliente, serviço, responsável e prazo bem definidos.</p><button class="btn pri" data-m="taskNew">＋ Nova demanda</button></div><div class="task-filterbar"><div class="task-filter"><small>CLIENTE</small><select id="taskClient"><option value="all">Todos os clientes</option>${D.clients.map(c=>`<option value="${c.id}" ${taskClientFilter===c.id?'selected':''}>${E(c.name)}</option>`).join('')}</select></div><div class="task-filter"><small>SERVIÇO</small><select id="taskService"><option value="all">Todos os serviços</option>${['social_media','storymaker','trafego','identidade_visual','administrativo'].map(s=>`<option value="${s}" ${taskServiceFilter===s?'selected':''}>${E(lab(s))}</option>`).join('')}</select></div><div class="task-filter"><small>RESPONSÁVEL</small><select id="taskOwner"><option value="all">Toda equipe</option>${D.profiles.map(p=>`<option value="${p.user_id}" ${taskOwnerFilter===p.user_id?'selected':''}>${E(p.display_name)}</option>`).join('')}<option value="none" ${taskOwnerFilter==='none'?'selected':''}>Sem responsável</option></select></div>${dirty?'<button class="btn ghost small task-filter-clear" data-taskclear>Limpar filtros</button>':''}</div><div class="task-filter-summary"><span>${filtered.length} demanda${filtered.length===1?'':'s'}</span>${taskClientFilter!=='all'?`<b>${E(cl(taskClientFilter)?.name||'Cliente')}</b>`:''}${taskServiceFilter!=='all'?`<b>${E(lab(taskServiceFilter))}</b>`:''}${taskOwnerFilter!=='all'?`<b>${taskOwnerFilter==='none'?'Sem responsável':E(profile(taskOwnerFilter)?.display_name||'Responsável')}</b>`:''}</div><div class="kan">${cols.map(([s,n])=>`<section class="col"><h4>${n}</h4>${filtered.filter(t=>t.status===s).map(t=>{let clientName=cl(t.client_id)?.name||'Colab · Interno',ownerName=profile(t.assigned_to)?.display_name||'Sem responsável';return`<article class="task service-card-task svc-card-${t.service||'other'}" data-taskopen="${t.id}" data-client="${t.client_id||''}" data-owner="${t.assigned_to||''}" data-service="${t.service||''}"><div class="task-clientline">${E(clientName)}</div><b class="task-title-main">${E(t.title)}</b><div class="task-service-line"><span class="task-service-tag svc-${t.service||'other'}"><b>${E(svcIcon(t.service))}</b>${E(lab(t.service))}</span></div><div class="task-ownerline ${!t.assigned_to?'needs-owner':''}"><div class="task-owneravatar">${t.assigned_to?E(ini(ownerName)):'!'}</div><div class="task-ownerinfo"><small>RESPONSÁVEL</small><b>${E(ownerName)}</b></div>${t.due_date?`<div class="task-duedate">PRAZO<b>${fmtDate(t.due_date)}</b></div>`:'<div class="task-duedate">PRAZO<b>Sem data</b></div>'}</div><select data-status="${t.id}">${cols.map(([v,l])=>`<option value="${v}" ${v===t.status?'selected':''}>${l}</option>`).join('')}</select></article>`}).join('')||'<div class="empty">Sem demandas.</div>'}</section>`).join('')}</div>`}
function contentItemsFor(clientId,month){let plan=D.plans.find(p=>p.client_id===clientId&&dateMonth(p.month)===month);return D.contents.filter(c=>c.client_id===clientId&&(dateMonth(c.publication_date)===month||(plan&&c.monthly_plan_id===plan.id)))}
function contentPage(){let c=cl(contentClient),items=contentItemsFor(contentClient,contentMonth),plan=D.plans.find(p=>p.client_id===contentClient&&dateMonth(p.month)===contentMonth),pills=D.pillars.filter(p=>p.client_id===contentClient&&p.active);let strategy=`<section class="strategy"><div class="head"><div><small class="ey">ESTRATÉGIA DE ${new Date(contentMonth+'-01T12:00:00').toLocaleDateString('pt-BR',{month:'long',year:'numeric'}).toUpperCase()}</small><h3>${E(plan?.theme||'Defina o foco do mês')}</h3><p class="muted">${E(plan?.main_goal||'Cadastre o objetivo principal para o planejamento ficar estratégico, não só cronológico.')}</p></div><button class="btn ghost small" data-m="strategy">Editar estratégia</button></div>${pills.map(p=>{let tar=D.targets.find(t=>t.plan_id===plan?.id&&t.pillar_id===p.id)?.target_count||0,done=items.filter(x=>x.editorial_pillar_id===p.id).length,pc=tar?Math.min(100,done/tar*100):0;return`<div class="pillarbar"><div><div class="head"><small>${E(p.name)}</small><small>${done}/${tar||'—'}</small></div><div class="progress"><i style="width:${pc}%"></i></div></div><span class="tag">${E(p.objective||'Linha editorial')}</span></div>`}).join('')||'<div class="empty">Ainda não há linhas editoriais para este cliente.</div>'}<button class="btn ghost small" data-m="pillars">＋ Linhas editoriais</button></section>`;let calItems=items.filter(x=>x.publication_date).map(x=>({date:x.publication_date,type:'content',client:x.client_id,title:x.title,meta:`${fmt(x.format)} · ${pillar(x.editorial_pillar_id)?.name||cs(x.status)}`,status:x.status,id:x.id}));let body=contentMode==='calendar'?calendarGrid(contentMonth,calItems):contentMode==='strategy'?strategy+contentList(items):contentMode==='feed'?feedPreviewGrid(items,false):contentMode==='creation'?creationBoard(items):contentList(items);let undated=items.filter(x=>!x.publication_date);return`<div class="toolbar"><p class="muted">Planejamento editorial por cliente, mês, objetivo e linha editorial.</p><button class="btn pri" data-m="contentNew">＋ Novo conteúdo</button><button class=\"btn pri\" onclick=\"V='production';render()\">◉ StoryMaker / Eventos</button></div><div class="filters"><select id="contentClient">${D.clients.filter(c=>c.active).map(x=>`<option value="${x.id}" ${contentClient===x.id?'selected':''}>${E(x.name)}</option>`).join('')}</select><input id="contentMonth" type="month" value="${contentMonth}"><div class="tabs"><button data-cmode="calendar" class="${contentMode==='calendar'?'on':''}">Calendário</button><button data-cmode="strategy" class="${contentMode==='strategy'?'on':''}">Estratégia</button><button data-cmode="feed" class="${contentMode==='feed'?'on':''}">Feed</button><button data-cmode="creation" class="${contentMode==='creation'?'on':''}">Criação</button><button data-cmode="list" class="${contentMode==='list'?'on':''}">Lista</button></div></div>${contentMode==='calendar'?strategy:''}${contentMode==='calendar'?`<div class="content-calendar-heading"><small class="ey">CALENDÁRIO EDITORIAL</small></div>`:''}${body}${undated.length&&contentMode==='calendar'?`<section class="panel" style="margin-top:14px"><div class="head"><h3>Conteúdos sem data</h3><span class="tag">${undated.length}</span></div>${contentList(undated)}</section>`:''}`}
function contentList(items){return`<section class="panel content-list">${items.map(c=>`<article class="content-row status-${c.status}" data-contentopen="${c.id}"><div class="head"><div><b>${E(c.title)}</b><div class="chips"><span class="tag">${E(fmt(c.format))}</span>${pillar(c.editorial_pillar_id)?`<span class="tag o">${E(pillar(c.editorial_pillar_id).name)}</span>`:''}<span class="tag ${c.status==='published'?'g':c.status==='scheduled'?'b':c.status==='approval'?'y':c.status==='changes_requested'?'r':['production','editing'].includes(c.status)?'o':''}">${E(cs(c.status))}</span></div></div><small class="muted">${fmtDate(c.publication_date)}</small></div></article>`).join('')||'<div class="empty">Nenhum conteúdo neste mês.</div>'}</section>`}
function feedTargetFor(clientSide=false,items=[]){let cid=clientSide?M.client_id:contentClient,mon=clientSide?clientMonth:contentMonth,plan=(D.plans||[]).find(p=>p.client_id===cid&&dateMonth(p.month)===mon),target=Number(plan?.feed_target_count||0);if(!target&&plan)target=(D.targets||[]).filter(t=>t.plan_id===plan.id).reduce((n,t)=>n+Number(t.target_count||0),0);return Math.max(target||items.length,items.length)}
async function saveFeedTarget(value){try{let p=await ensurePlan(contentClient,contentMonth),v=value==='auto'?null:Number(value);await patch('monthly_editorial_plans',p.id,{feed_target_count:v,updated_at:new Date().toISOString()});await load();render();toast(v?`Prévia ajustada para ${v} conteúdos`:'Prévia em modo automático')}catch(x){toast(x.message)}}
function feedPreviewGrid(items,clientSide=false){let approved=items.filter(c=>['scheduled','published'].includes(c.status)),src=clientSide?approved:(feedMode==='simulate'?items:approved);src=[...src].sort((a,b)=>String(b.publication_date||'0000').localeCompare(String(a.publication_date||'0000')));let target=feedTargetFor(clientSide,items),plan=(D.plans||[]).find(p=>p.client_id===(clientSide?M.client_id:contentClient)&&dateMonth(p.month)===(clientSide?clientMonth:contentMonth)),chosen=plan?.feed_target_count?String(plan.feed_target_count):'auto',slots=!clientSide&&feedMode==='simulate'?Math.max(0,target-src.length):0;return`<section class="panel feed-panel"><div class="head"><div><small class="ey">PRÉVIA DO FEED</small><h3>${clientSide?'Como seu feed está tomando forma':'Visual do Instagram'}</h3><p class="muted">${clientSide?'Conteúdos aprovados, organizados como vão aparecer no perfil.':'Veja o mês inteiro em uma grade de 3 colunas, como no Instagram.'}</p></div>${!clientSide?`<div class="tabs"><button data-feedmode="approved" class="${feedMode==='approved'?'on':''}">Aprovados</button><button data-feedmode="simulate" class="${feedMode==='simulate'?'on':''}">Simular mês</button></div>`:''}</div>${!clientSide?`<div class="filters" style="margin-top:12px"><label style="font-size:11px;font-weight:800;color:#888">Quantidade do mês</label><select id="feedTargetSelect"><option value="auto" ${chosen==='auto'?'selected':''}>Automático</option><option value="1" ${chosen==='1'?'selected':''}>1 conteúdo</option><option value="2" ${chosen==='2'?'selected':''}>2 conteúdos</option><option value="3" ${chosen==='3'?'selected':''}>3 conteúdos</option><option value="4" ${chosen==='4'?'selected':''}>4 conteúdos</option><option value="5" ${chosen==='5'?'selected':''}>5 conteúdos</option><option value="6" ${chosen==='6'?'selected':''}>6 conteúdos</option><option value="7" ${chosen==='7'?'selected':''}>7 conteúdos</option><option value="8" ${chosen==='8'?'selected':''}>8 conteúdos</option><option value="9" ${chosen==='9'?'selected':''}>9 conteúdos</option><option value="10" ${chosen==='10'?'selected':''}>10 conteúdos</option><option value="11" ${chosen==='11'?'selected':''}>11 conteúdos</option><option value="12" ${chosen==='12'?'selected':''}>12 conteúdos</option><option value="13" ${chosen==='13'?'selected':''}>13 conteúdos</option><option value="14" ${chosen==='14'?'selected':''}>14 conteúdos</option><option value="15" ${chosen==='15'?'selected':''}>15 conteúdos</option></select><span class="tag">${target} espaços</span></div>`:''}<div class="feed-grid">${src.map(c=>{let a=currentAsset(c);return`<article class="feed-cell" data-contentopen="${c.id}"><div class="feed-media" ${a?`data-asset-path="${E(a.storage_path)}" data-mime="${E(a.mime_type||'')}" data-filename="${E(a.file_name)}" data-thumb="1"`:''}>${a?(a.mime_type||'').startsWith('video/')?'▶':'▧':'Sem arte'}<span>${E(fmt(c.format))}</span></div></article>`}).join('')}${Array.from({length:slots},()=>`<article class="feed-cell"><div class="feed-media" style="display:flex;flex-direction:column;gap:4px"><b style="font-size:24px;color:#444">＋</b><small style="color:#555;font-weight:800">A planejar</small></div></article>`).join('')}${!src.length&&!slots?'<div class="empty feed-empty">Ainda não há conteúdos para montar esta prévia.</div>':''}</div></section>`}
function ideasPage(){let newi=D.insights.filter(x=>x.status==='new'),brief=D.briefings.filter(x=>dateMonth(x.month)===monthNow());return`<div class="toolbar"><p class="muted">Ideias, referências e briefings enviados pelos clientes.</p><button class="btn pri" data-m="insightNewTeam">＋ Nova ideia</button></div><div class="stats"><article class="stat"><span>Novos insights</span><b>${newi.length}</b><small>aguardando triagem</small></article><article class="stat"><span>Briefings do mês</span><b>${brief.length}</b><small>recebidos</small></article><article class="stat"><span>Convertidos</span><b>${D.insights.filter(x=>x.status==='converted').length}</b><small>viraram conteúdo</small></article><article class="stat"><span>Referências internas</span><b>${D.refs.length}</b><small>na biblioteca</small></article></div><div class="grid2"><section class="panel"><div class="head"><h3>Caixa de ideias dos clientes</h3></div>${D.insights.map(i=>ideaCard(i,true)).join('')||'<div class="empty">Nenhum insight enviado ainda.</div>'}</section><section class="panel"><div class="head"><h3>Briefings mensais</h3></div>${D.briefings.slice(0,8).map(b=>`<div class="row"><span class="dot ${b.status==='submitted'?'g':''}"></span><div class="grow"><b>${E(cl(b.client_id)?.name||'')}</b><small>${new Date(b.month+'T12:00:00').toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</small></div><button class="btn ghost small" data-briefopen="${b.id}">Abrir</button></div>`).join('')||'<div class="empty">Nenhum briefing ainda.</div>'}</section></div>`}
function ideaCard(i,team=false){let a=D.insightAssets.filter(x=>x.insight_id===i.id);return`<article class="idea ${i.status==='new'?'new':''}" style="margin:8px 0"><div class="head"><div><small class="ey">${E(cl(i.client_id)?.name||'')}</small><h3>${E(i.title)}</h3></div><span class="tag ${i.status==='new'?'o':i.status==='converted'?'g':''}">${E(i.status)}</span></div><p>${E(i.notes||'')}</p><div class="chips">${i.source_url?`<a class="btn ghost small" href="${E(i.source_url)}" target="_blank">Abrir referência ↗</a>`:''}${a.map(x=>`<button class="btn ghost small" data-file="${E(x.storage_path)}">${E(x.file_name)}</button>`).join('')}${team&&i.status!=='converted'?`<button class="btn pri small" data-convert="${i.id}">Transformar em conteúdo</button>`:''}</div></article>`}
function productionPage(){let ev=D.events.filter(e=>!productionClient||e.client_id===productionClient);return`<div class="toolbar"><p class="muted">Gravações, StoryMaker, roteiros, eventos e checklists.</p><button class="btn pri" data-m="eventNew">＋ Nova produção</button></div><div class="filters"><select id="productionClient"><option value="">Todos os clientes</option>${D.clients.filter(c=>c.active).map(c=>`<option value="${c.id}" ${productionClient===c.id?'selected':''}>${E(c.name)}</option>`).join('')}</select></div><div class="grid2">${ev.map(e=>{let rec=D.receivables.find(r=>r.event_id===e.id&&r.category==='extra'),isDelivery=['storymaker','recording','event'].includes(e.event_type),links=[['Material bruto',e.delivery_raw_url],['Vídeos editados',e.delivery_edited_url],['Fotos',e.delivery_photos_url],['Pasta completa',e.delivery_folder_url]].filter(x=>x[1]),ds=e.delivery_status||'pending',dsl=ds==='delivered'?'Entrega concluída':ds==='organizing'?'Organizando material':'Aguardando entrega';return`<section class="panel"><div class="head"><div><small class="ey">${E(lab(e.event_type))}</small><h3>${E(e.title)}</h3><p class="muted">${E(cl(e.client_id)?.name||'')} · ${fmtDate(String(e.starts_at||'').slice(0,10))} ${e.starts_at?'às '+fmtTime(e.starts_at):''}</p></div><div class="actions">${e.is_extra?`<span class="tag ${rec?.status==='paid'?'g':'y'}">Extra ${money(e.extra_amount)}</span>`:''}<button class="btn ghost small" data-eventedit="${e.id}">Editar evento</button></div></div><div class="chips"><span class="tag">${e.contracted_hours?e.contracted_hours+'h contratadas':'Horas não informadas'}</span>${e.location?`<span class="tag">${E(e.location)}</span>`:''}<button class="btn ghost small" data-shotadd="${e.id}" data-client="${e.client_id}" data-type="${e.event_type}">＋ Take</button></div>${D.shots.filter(s=>s.event_id===e.id).map(s=>`<label class="shot"><input data-shot="${s.id}" type="checkbox" ${s.completed?'checked':''}> ${E(s.text)}</label>`).join('')||'<div class="empty">Sem checklist.</div>'}${e.script_text?`<details style="border-top:1px solid #292929;margin-top:14px;padding-top:14px"><summary style="cursor:pointer;font-weight:900;color:var(--o)">ROTEIRO / FALAS · Ver roteiro</summary><div style="white-space:pre-wrap;line-height:1.55;margin-top:10px">${E(e.script_text)}</div>${e.script_notes?`<p class="muted" style="margin-bottom:0"><b>Orientações:</b> ${E(e.script_notes)}</p>`:''}</details>`:''}${isDelivery?`<div style="border-top:1px solid #292929;margin-top:14px;padding-top:14px"><div class="head"><div><small class="ey">ENTREGA / DRIVE</small><h3 style="margin:4px 0">Entregáveis do evento</h3></div><span class="tag ${ds==='delivered'?'g':ds==='organizing'?'y':''}">${dsl}</span></div>${links.length?`<div class="delivery-grid">${links.map(([n,u])=>`<a class="delivery-link" href="${E(u)}" target="_blank" rel="noopener"><span>${E(n)}</span><b>↗</b></a>`).join('')}</div>`:'<p class="muted">Nenhum link de entrega adicionado ainda.</p>'}<button class="btn pri small" style="margin-top:10px" data-eventedit="${e.id}">${links.length?'Gerenciar entrega':'＋ Adicionar links da entrega'}</button></div>`:''}</section>`}).join('')||'<div class="empty">Nenhuma produção cadastrada.</div>'}</div>`}
function activeContractsForMonth(month){let start=month+'-01',[y,m]=month.split('-').map(Number),end=new Date(y,m,0);let endISO=end.getFullYear()+'-'+String(end.getMonth()+1).padStart(2,'0')+'-'+String(end.getDate()).padStart(2,'0');return D.contracts.filter(c=>c.status==='active'&&c.start_date<=endISO&&c.end_date>=start)}
function recurringCostRow(x){let d=daysBetween(today(),x.next_due_date),st=d<0?'Vencida':d===0?'Vence hoje':d===1?'Vence amanhã':d+' dias',rec={monthly:'Mensal',annual:'Anual',one_time:'Única'}[x.recurrence]||x.recurrence;return`<div class="row"><span class="dot ${d<0?'r':d<=3?'y':''}"></span><div class="grow"><b>${E(x.name)} · ${money(x.amount)}</b><small>${E(rec)} · ${E(x.vendor||'COLAB')} · ${E(profile(x.responsible_to)?.display_name||'Sem responsável')} · ${fmtDate(x.next_due_date)}</small></div><div class="actions"><span class="tag ${d<0?'r':d<=3?'y':''}">${E(st)}</span><button class="btn pri small" data-paycost="${x.id}">Marcar pago</button></div></div>`}
function financePage(){let costs=(D.recurringCosts||[]).filter(x=>x.status==='active').slice().sort((a,b)=>String(a.next_due_date).localeCompare(String(b.next_due_date))),rec=D.receivables.filter(r=>dateMonth(r.competence_month||r.due_date)===financeMonth),exp=D.expenses.filter(x=>dateMonth(x.expense_date)===financeMonth),wd=D.withdrawals.filter(x=>dateMonth(x.withdrawal_date)===financeMonth),contracts=activeContractsForMonth(financeMonth),forecast=sum(rec.filter(x=>x.status!=='cancelled'),'amount'),received=sum(rec.filter(x=>x.status==='paid'),'amount'),open=sum(rec.filter(x=>x.status==='pending'),'amount'),expenses=sum(exp.filter(x=>x.status==='paid'),'amount'),withdraw=sum(wd,'amount'),result=received-expenses-withdraw,cash=Number(D.finance.opening_cash||0)+sum(D.receivables.filter(x=>x.status==='paid'),'amount')-sum(D.expenses.filter(x=>x.status==='paid'),'amount')-sum(D.withdrawals,'amount'),recurring=sum(contracts,'monthly_fee');return`<div class="toolbar"><p class="muted">Receita, mensalidades, extras, despesas, retiradas e caixa da Colab.</p><div class="quick"><button class="btn pri" data-m="contractNew">＋ Contrato</button><button class="btn ghost" data-m="recurringCostNew">＋ Conta / assinatura</button><button class="btn ghost" data-m="expenseNew">＋ Despesa</button><button class="btn ghost" data-m="withdrawalNew">＋ Retirada</button></div></div><div class="filters"><input id="financeMonth" type="month" value="${financeMonth}"><button class="btn ghost small" data-m="receivableNew">＋ Recebimento avulso</button><button class="btn ghost small" data-m="financeSettings">⚙ Caixa/Reserva</button></div><div class="finance-head"><article class="finance-card"><span>Receita recorrente</span><b>${money(recurring)}</b></article><article class="finance-card"><span>Faturamento previsto</span><b>${money(forecast)}</b></article><article class="finance-card"><span>Recebido</span><b class="moneypos">${money(received)}</b></article><article class="finance-card"><span>A receber</span><b>${money(open)}</b></article><article class="finance-card"><span>Despesas pagas</span><b class="moneyneg">${money(expenses)}</b></article><article class="finance-card"><span>Retiradas sócias</span><b class="moneyneg">${money(withdraw)}</b></article><article class="finance-card"><span>Resultado do mês</span><b class="${result>=0?'moneypos':'moneyneg'}">${money(result)}</b></article><article class="finance-card"><span>Caixa atual</span><b>${money(cash)}</b><small class="muted">Reserva: ${money(D.finance.reserve_target)}</small></article></div><div class="grid2"><section class="panel"><div class="head"><h3>Recebimentos</h3><span class="tag">${rec.length}</span></div>${rec.map(r=>`<div class="row"><span class="dot ${r.status==='paid'?'g':r.due_date<today()?'r':'y'}"></span><div class="grow"><b>${E(cl(r.client_id)?.name||r.external_contact_name||'Avulso')} · ${money(r.amount)}</b><small>${E(r.description)} · vence ${fmtDate(r.due_date)}</small></div><div class="actions">${r.status==='paid'?`<span class="tag g">Pago</span>`:`<button class="btn pri small" data-payrec="${r.id}">Marcar pago</button>`}<button type="button" class="btn danger small" data-receivabledelete="${r.id}">Excluir</button></div></div>`).join('')||'<div class="empty">Nenhuma cobrança neste mês.</div>'}</section><section class="panel"><div class="head"><h3>Despesas</h3><button class="btn ghost small" data-m="expenseNew">＋</button></div>${exp.map(x=>`<div class="row"><span class="dot ${x.status==='paid'?'g':'y'}"></span><div class="grow"><b>${E(x.description)} · ${money(x.amount)}</b><small>${E(x.category)} ${x.client_id?'· '+E(cl(x.client_id)?.name||''):''}</small></div>${x.status==='paid'?`<span class="tag g">Pago</span>`:`<button class="btn pri small" data-payexp="${x.id}">Pagar</button>`}</div>`).join('')||'<div class="empty">Nenhuma despesa neste mês.</div>'}</section></div><section class="panel" style="margin-top:14px"><div class="head"><div><small class="ey">CONTAS & ASSINATURAS</small><h3>O que a Colab precisa pagar</h3><p class="muted">Ferramentas, aplicativos e custos recorrentes com próximo vencimento.</p></div><button class="btn ghost small" data-m="recurringCostNew">＋ Nova conta</button></div>${costs.map(recurringCostRow).join('')||'<div class="empty">Nenhuma conta recorrente cadastrada.</div>'}</section><section class="panel"><div class="head"><div><small class="ey">CONTRATOS</small><h3>Mensais & avulsos</h3></div></div><div class="grid3">${D.contracts.filter(c=>c.status==='active').map(contractCard).join('')||'<div class="empty">Cadastre contratos mensais ou avulsos.</div>'}</div></section><section class="panel" style="margin-top:14px"><div class="head"><h3>Retiradas das sócias</h3><button class="btn ghost small" data-m="withdrawalNew">＋</button></div>${wd.map(w=>`<div class="row"><div class="avatar">${E(ini(w.partner_name))}</div><div class="grow"><b>${E(w.partner_name)} · ${money(w.amount)}</b><small>${fmtDate(w.withdrawal_date)} · ${E(w.withdrawal_type)}</small></div><span class="tag">Retirada</span></div>`).join('')||'<div class="empty">Nenhuma retirada neste mês.</div>'}</section>`}
function contractCard(c){let total=Math.max(1,monthsInclusive(c.start_date,c.end_date)),elapsed=Math.min(total,Math.max(1,monthsInclusive(c.start_date,today()))),days=daysBetween(today(),c.end_date);return`<article class="finance-card"><small class="ey">${E(cl(c.client_id)?.name||'')}</small><h3>${money(c.monthly_fee)}/mês</h3><p class="muted">Vencimento dia ${c.billing_day} · ${E(c.payment_method||'Pagamento não definido')}</p><div class="contract-progress"><div class="head"><small>Mês ${elapsed} de ${total}</small><span class="tag ${days<0||days<=7?'r':days<=30?'y':''}">${days<0?'Vencido':days<=7?'Urgente · '+days+' dias':days<=15?'Atenção · '+days+' dias':days<=30?'Renovar · '+days+' dias':days+' dias'}</span></div><div class="progress"><i style="width:${Math.min(100,elapsed/total*100)}%"></i></div></div><p class="muted">${E(c.package_summary||'Sem resumo do plano.')}</p></article>`}
function monthsInclusive(a,b){if(!a||!b)return 1;let A=new Date(a+'T12:00:00'),B=new Date(b+'T12:00:00');return(Math.max(0,(B.getFullYear()-A.getFullYear())*12+B.getMonth()-A.getMonth())+1)}
function opStageLabel(v){return({new:'Novo contato',contacted:'Contato feito',meeting:'Reunião',proposal:'Proposta enviada',negotiation:'Em negociação',won:'Fechado 🧡',lost:'Não avançou'})[v]||v}
function opServiceLabel(v){return({social_media:'Social Media',storymaker:'StoryMaker',trafego:'Tráfego Pago',identidade_visual:'Identidade Visual',complete:'Gerenciamento completo',other:'Outro'})[v]||v||'Serviço a definir'}
function commercialPage(){let stages=['new','contacted','meeting','proposal','negotiation','won','lost'],ops=D.opportunities||[],active=ops.filter(x=>!['won','lost'].includes(x.stage)),potential=sum(active,'estimated_value'),follow=active.filter(x=>x.next_action_date&&x.next_action_date<=today());return`<div class="toolbar"><div><small class="ey">COMERCIAL COLAB</small><h2 style="margin:5px 0">Oportunidades & negociações</h2><p class="muted">Do primeiro contato ao início de uma nova Colab.</p></div><button class="btn pri" data-m="opportunityNew">＋ Nova oportunidade</button></div><div class="stats"><article class="stat"><span>Pipeline aberto</span><b>${active.length}</b><small>oportunidades em andamento</small></article><article class="stat"><span>Valor potencial</span><b>${money(potential)}</b><small>estimativa do pipeline</small></article><article class="stat ${follow.length?'attention':''}"><span>Follow-ups</span><b>${follow.length}</b><small>${follow.length?'para fazer agora':'nenhum pendente'}</small></article><article class="stat"><span>Fechados</span><b>${ops.filter(x=>x.stage==='won').length}</b><small>novas Colabs</small></article></div><div class="kan commercial-kan">${stages.map(s=>`<section class="col"><h4>${opStageLabel(s)}</h4>${ops.filter(x=>x.stage===s).map(x=>`<article class="task commercial-card"><small class="ey">${E(opServiceLabel(x.service_interest))}</small><b>${E(x.name)}</b><p class="muted" style="margin:6px 0">${E(x.contact_name||x.instagram||x.phone||x.email||x.segment||'Contato a completar')}</p><div class="chips" style="margin:8px 0">${x.owner_id?`<span class="tag o">${E(profile(x.owner_id)?.display_name||'Responsável')}</span>`:''}${Number(x.estimated_value||0)?`<span class="tag">${money(x.estimated_value)}</span>`:''}${x.source?`<span class="tag">${E(x.source)}</span>`:''}</div>${x.next_action?`<div class="note" style="margin:8px 0"><b>Próxima ação</b><br>${E(x.next_action)}${x.next_action_date?` · ${fmtDate(x.next_action_date)}`:''}</div>`:''}<select data-opstage="${x.id}">${stages.map(v=>`<option value="${v}" ${x.stage===v?'selected':''}>${opStageLabel(v)}</option>`).join('')}</select><div class="actions" style="margin-top:8px"><button class="btn ghost small" data-opedit="${x.id}">Editar</button>${x.stage==='won'&&!x.converted_client_id?`<button class="btn pri small" data-opconvert="${x.id}">Transformar em cliente</button>`:''}${x.converted_client_id?'<span class="tag g">Cliente criado ✓</span>':''}</div></article>`).join('')||'<div class="empty">Nenhuma oportunidade.</div>'}</section>`).join('')}</div>`}
function colabClientId(){return D.clients.find(c=>String(c.slug||'').toLowerCase()==='colab'||String(c.name||'').toUpperCase()==='COLAB')?.id||''}
function dnaItemRow(x){return`<div class="row"><span class="dot ${x.status==='done'?'g':x.status==='doing'?'o':''}"></span><div class="grow"><b>${E(x.title)}</b><small>${E(x.description||'')}${x.due_date?' · '+fmtDate(x.due_date):''}</small></div>${x.link_url?`<a class="btn ghost small" href="${E(x.link_url)}" target="_blank" rel="noopener">Abrir ↗</a>`:''}<select data-dnastatus="${x.id}" style="max-width:150px"><option value="idea" ${x.status==='idea'?'selected':''}>Ideia</option><option value="planned" ${x.status==='planned'?'selected':''}>Planejado</option><option value="doing" ${x.status==='doing'?'selected':''}>Em andamento</option><option value="done" ${x.status==='done'?'selected':''}>Concluído</option><option value="paused" ${x.status==='paused'?'selected':''}>Pausado</option></select></div>`}
function dnaPage(){let cid=colabClientId(),items=D.dnaItems||[],parts=D.partnerships||[],labs=D.labItems||[],strat=items.filter(x=>x.category==='strategy'),campaigns=items.filter(x=>x.category==='campaign'),brand=items.filter(x=>x.category==='brand');return`<section class="hero"><div><small class="ey">DNA Colab</small><h2>Onde a gente constrói o que é nosso.</h2><p class="muted">Conteúdo, posicionamento, parcerias, campanhas e experimentos da própria Colab.</p></div></section><div class="moregrid dna-shortcuts"><button data-dnago="content"><b>▦ Conteúdo Colab</b><p class="muted">Calendário, feed e planejamento.</p></button><button data-dnago="creation"><b>✦ Studio de Criação</b><p class="muted">Canva e fluxo interno.</p></button><button data-dnago="ideas"><b>◎ Banco de Ideias</b><p class="muted">Pautas e insights nossos.</p></button><button data-dnago="library"><b>▧ Biblioteca Colab</b><p class="muted">Referências e acervo da marca.</p></button></div><div class="grid2"><section class="panel"><div class="head"><div><small class="ey">ESTRATÉGIA & POSICIONAMENTO</small><h3>O que queremos construir</h3></div><button class="btn ghost small" data-m="dnaItemNew" data-category="strategy">＋</button></div>${strat.map(dnaItemRow).join('')||'<div class="empty">Nenhum direcionamento cadastrado.</div>'}</section><section class="panel"><div class="head"><div><small class="ey">CAMPANHAS & MOVIMENTOS</small><h3>O que vamos colocar na rua</h3></div><button class="btn ghost small" data-m="dnaItemNew" data-category="campaign">＋</button></div>${campaigns.map(dnaItemRow).join('')||'<div class="empty">Nenhuma campanha planejada.</div>'}</section></div><div class="grid2" style="margin-top:14px"><section class="panel"><div class="head"><div><small class="ey">PARCERIAS</small><h3>Relações que fazem a Colab crescer</h3></div><button class="btn ghost small" data-m="partnershipNew">＋ Parceria</button></div>${parts.map(x=>`<div class="row"><span class="dot ${x.stage==='active'?'g':x.stage==='talking'?'o':''}"></span><div class="grow"><b>${E(x.name)}</b><small>${E(x.category||'Parceiro potencial')}${x.next_action?` · ${E(x.next_action)}`:''}${x.next_action_date?' · '+fmtDate(x.next_action_date):''}</small></div><select data-partstage="${x.id}" style="max-width:145px"><option value="mapped" ${x.stage==='mapped'?'selected':''}>Mapeada</option><option value="talking" ${x.stage==='talking'?'selected':''}>Conversando</option><option value="aligned" ${x.stage==='aligned'?'selected':''}>Alinhada</option><option value="active" ${x.stage==='active'?'selected':''}>Ativa</option><option value="paused" ${x.stage==='paused'?'selected':''}>Pausada</option></select></div>`).join('')||'<div class="empty">Nenhuma parceria cadastrada.</div>'}</section><section class="panel"><div class="head"><div><small class="ey">MARCA COLAB</small><h3>Ativos e materiais nossos</h3></div><button class="btn ghost small" data-m="dnaItemNew" data-category="brand">＋</button></div>${brand.map(dnaItemRow).join('')||'<div class="empty">Adicione materiais, links e movimentos da marca.</div>'}</section></div><section class="panel" style="margin-top:14px"><div class="head"><div><small class="ey">LAB COLAB</small><h3>Testar antes de virar padrão 🧪</h3><p class="muted">Experimentos, formatos e processos que queremos validar.</p></div><button class="btn pri small" data-m="labItemNew">＋ Experimento</button></div>${labs.map(x=>`<div class="row"><span class="dot ${x.status==='standard'||x.status==='worked'?'g':x.status==='testing'?'o':x.status==='didnt_work'?'r':''}"></span><div class="grow"><b>${E(x.title)}</b><small>${E(x.area||'LAB')}${x.hypothesis?' · '+E(x.hypothesis):''}</small></div><select data-labstatus="${x.id}" style="max-width:150px"><option value="idea" ${x.status==='idea'?'selected':''}>Ideia</option><option value="testing" ${x.status==='testing'?'selected':''}>Testando</option><option value="worked" ${x.status==='worked'?'selected':''}>Funcionou</option><option value="didnt_work" ${x.status==='didnt_work'?'selected':''}>Não funcionou</option><option value="standard" ${x.status==='standard'?'selected':''}>Padrão Colab</option></select></div>`).join('')||'<div class="empty">Nenhum experimento no LAB ainda.</div>'}</section>`}

function muralNoteCard(n){let author=profile(n.author_id)?.display_name||'Equipe',recipient=n.recipient_id?(profile(n.recipient_id)?.display_name||'Equipe'):'Todo mundo',style=n.style||'orange',x=Math.max(12,Number(n.x||24)),y=Math.max(12,Number(n.y||24));return`<article class="mural-note ${E(style)} ${n.pinned?'pinned':''}" data-muralnote="${n.id}" style="left:${x}px;top:${y}px"><div class="mural-note-head"><span class="mural-emoji">${E(n.emoji||'🧡')}</span><div class="mural-note-tools"><button type="button" data-muralpin="${n.id}" title="${n.pinned?'Desafixar':'Fixar'}">${n.pinned?'●':'○'}</button><button type="button" data-muralresolve="${n.id}" title="Marcar como resolvido">✓</button><button type="button" data-muraldelete="${n.id}" title="Excluir">×</button></div></div><p>${E(n.body).replace(/\n/g,'<br>')}</p><div class="mural-note-foot"><span>${E(author)}</span><span>→ ${E(recipient)}</span></div></article>`}
function teamStatusMeta(k){return({on:['Modo Colab: ON','🧡'],creating:['Em criação','✦'],hands_on:['Mão na massa','⚡'],coffee:['Hora do café','☕'],break:['No intervalo','🌿'],capture:['Em captação','🎬'],focus:['Foco total','🎧'],done:['Por hoje, concluído','✓'],custom:['Status do momento','👀']})[k]||['Modo Colab: ON','🧡']}
function teamStatusStrip(){let sts=D.teamStatuses||[],me=sts.find(x=>x.user_id===S.user.id),cards=(D.profiles||[]).map(p=>{let s=sts.find(x=>x.user_id===p.user_id),meta=teamStatusMeta(s?.status_key),label=s?.status_text||meta[0],emoji=s?.emoji||meta[1],viewed=(s?.photo_viewed_by||[]).includes(S.user.id),hasPhoto=!!s?.photo_path&&!viewed;return`<div class=\"status-person\"><button type=\"button\" class=\"status-bubble ${hasPhoto?'has-photo':''}\" ${hasPhoto?`data-statusphoto=\"${s.id}\"`:''}><span>${E(ini(p.display_name))}</span>${hasPhoto?'<i>1×</i>':''}</button><b>${E(p.display_name)}</b><small>${E(emoji)} ${E(label)}</small></div>`}).join('');return`<section class=\"team-status-zone\"><div class=\"head\"><div><small class=\"ey\">AGORA NA COLAB</small><h3></h3><p class=\"muted\">Um pedacinho do que cada uma está fazendo agora.</p></div></div><div class=\"status-people\">${cards}</div><details class=\"status-editor\"><summary>${me?'Atualizar meu status':'Definir meu status'}</summary><form id=\"teamStatusForm\"><div class=\"status-form-grid\"><div class=\"field\"><label>Modo</label><select name=\"status_key\">${[['on','Modo Colab: ON'],['creating','Em criação'],['hands_on','Mão na massa'],['coffee','Hora do café'],['break','No intervalo'],['capture','Em captação'],['focus','Foco total'],['done','Por hoje, concluído'],['custom','Personalizado']].map(([v,l])=>`<option value=\"${v}\" ${me?.status_key===v?'selected':''}>${l}</option>`).join('')}</select></div><div class=\"field\"><label>Escrever algo (opcional)</label><input name=\"status_text\" maxlength=\"80\" value=\"${E(me?.status_text||'')}\" placeholder=\"Ex.: criando a proposta da Nati\"></div><div class=\"field status-photo-field\"><label>Foto do momento · visualização única</label><input id=\"statusPhotoInput\" name=\"photo\" type=\"file\" accept=\"image/*\"><small class=\"muted\">Quando a outra pessoa abrir, a foto some para ela.</small></div></div><div class=\"actions\" style=\"margin-top:10px\"><button class=\"btn pri\">Atualizar status</button>${me?.photo_path?'<button type=\"button\" class=\"btn ghost\" data-statusclearphoto>Remover foto</button>':''}</div></form></details></section>`}
function muralPage(){let all=D.muralNotes||[],active=all.filter(x=>!x.resolved),done=all.filter(x=>x.resolved).slice(0,12);return`${teamStatusStrip()}<details class="mural-create"><summary>＋ Colar novo post-it</summary><form id="muralForm" class="mural-form"><div class="mural-form-grid"><div class="field mural-message"><label>Recado</label><textarea name="body" rows="3" maxlength="500" required placeholder="Carol, lembra de... / ideia aleatória / isso aqui é de milhões 👀"></textarea></div><div class="field"><label>Para quem?</label><select name="recipient_id"><option value="">Todo mundo</option>${(D.profiles||[]).map(p=>`<option value="${p.user_id}">${E(p.display_name)}</option>`).join('')}</select></div><div class="field"><label>Adesivo</label><select name="emoji">${['🧡','👀','💡','😂','🚨','✨','💥','🎬','☕'].map(x=>`<option value="${x}">${x}</option>`).join('')}</select></div><div class="field"><label>Post-it</label><select name="style"><option value="orange">Laranja</option><option value="light">Claro</option><option value="dark">Preto</option><option value="outline">Contorno</option></select></div></div><button class="btn pri" style="margin-top:10px">Colar no mural</button></form></details><div class="mural-board-wrap"><div class="mural-board" style="min-height:${Math.max(720,80+Math.ceil(Math.max(active.length,1)/3)*205)}px">${active.map(muralNoteCard).join('')||'<div class="mural-empty"><b>O mural está limpinho demais 😂</b><br><small>Cole o primeiro post-it ali em cima.</small></div>'}</div></div>${done.length?`<section class="panel mural-done"><div class="head"><div><small class="ey">RESOLVIDOS</small><h3>Já saiu da parede</h3></div><span class="tag">${done.length}</span></div>${done.map(n=>`<div class="row"><span>${E(n.emoji||'✓')}</span><div class="grow"><b>${E(n.body)}</b><small>${E(profile(n.author_id)?.display_name||'Equipe')}</small></div><button class="btn ghost small" data-muralrestore="${n.id}">Voltar ao mural</button></div>`).join('')}</section>`:''}`}
async function saveTeamStatus(e){e.preventDefault();let f=new FormData(e.currentTarget),key=f.get('status_key')||'on',meta=teamStatusMeta(key),text=String(f.get('status_text')||'').trim(),file=document.getElementById('statusPhotoInput')?.files?.[0],cur=(D.teamStatuses||[]).find(x=>x.user_id===S.user.id),photoPath=cur?.photo_path||null,viewed=cur?.photo_viewed_by||[],photoCreated=cur?.photo_created_at||null;try{if(file){if(file.size>8*1024*1024)throw Error('Escolha uma foto de até 8 MB.');let name=Date.now()+'-'+file.name.replace(/[^a-zA-Z0-9._-]/g,'-');photoPath=`${M.organization_id}/team-status/${S.user.id}/${name}`;await uploadRaw(file,photoPath);viewed=[];photoCreated=new Date().toISOString()}await api('/rest/v1/team_statuses?on_conflict=organization_id,user_id',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({organization_id:M.organization_id,user_id:S.user.id,status_key:key,status_text:text||null,emoji:meta[1],photo_path:photoPath,photo_created_at:photoCreated,photo_viewed_by:viewed,updated_at:new Date().toISOString()})});await load();render();toast('Status atualizado ✨')}catch(x){toast(x.message)}}
async function clearTeamStatusPhoto(){let s=(D.teamStatuses||[]).find(x=>x.user_id===S.user.id);if(!s)return;try{await patch('team_statuses',s.id,{photo_path:null,photo_created_at:null,photo_viewed_by:[],updated_at:new Date().toISOString()});await load();render();toast('Foto removida do status')}catch(x){toast(x.message)}}
async function viewTeamStatusPhoto(id){let s=(D.teamStatuses||[]).find(x=>x.id===id);if(!s)return;try{let path=await api('/rest/v1/rpc/view_team_status_photo',{method:'POST',body:JSON.stringify({p_status_id:id})});if(!path){await load();render();return toast('Essa foto já foi visualizada 👀')}let z=await api('/storage/v1/object/sign/client-media/'+encPath(path),{method:'POST',body:JSON.stringify({expiresIn:60})}),u=z.signedURL||z.signedUrl;if(u&&u.startsWith('/'))u=B+'/storage/v1'+u;await load();MD={type:'statusPhoto',url:u,name:profile(s.user_id)?.display_name||'Colab'};render()}catch(x){toast(x.message)}}
async function saveMuralNote(e){e.preventDefault();let f=new FormData(e.currentTarget),active=(D.muralNotes||[]).filter(x=>!x.resolved),i=active.length,x=24+(i%3)*270,y=24+Math.floor(i/3)*205,recipient=f.get('recipient_id')||null,body=String(f.get('body')||'').trim();if(!body)return;try{await api('/rest/v1/mural_notes',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({organization_id:M.organization_id,author_id:S.user.id,recipient_id:recipient,body,emoji:f.get('emoji')||'🧡',style:f.get('style')||'orange',x,y,pinned:false,resolved:false})});await load();render();toast('Post-it colado no mural 🧡')}catch(x){toast(x.message)}}
async function muralPatch(id,data,msg){try{await patch('mural_notes',id,{...data,updated_at:new Date().toISOString()});await load();render();if(msg)toast(msg)}catch(x){toast(x.message)}}
async function deleteMuralNote(id){if(!confirm('Tirar esse post-it do mural?'))return;try{await api('/rest/v1/mural_notes?id=eq.'+id,{method:'DELETE',headers:{Prefer:'return=minimal'}});await load();render();toast('Post-it removido')}catch(x){toast(x.message)}}
function bindMuralDrag(){let board=document.querySelector('.mural-board');if(!board)return;board.querySelectorAll('.mural-note').forEach(note=>{let h=note.querySelector('.mural-note-head');if(!h)return;h.onpointerdown=e=>{if(e.target.closest('button'))return;e.preventDefault();let sx=e.clientX,sy=e.clientY,ox=parseFloat(note.style.left)||0,oy=parseFloat(note.style.top)||0,pid=e.pointerId;h.setPointerCapture?.(pid);let move=ev=>{if(ev.pointerId!==pid)return;let nx=Math.max(8,Math.min(board.clientWidth-note.offsetWidth-8,ox+ev.clientX-sx)),ny=Math.max(8,Math.min(board.clientHeight-note.offsetHeight-8,oy+ev.clientY-sy));note.style.left=nx+'px';note.style.top=ny+'px'},up=async ev=>{if(ev.pointerId!==pid)return;h.removeEventListener('pointermove',move);h.removeEventListener('pointerup',up);h.removeEventListener('pointercancel',up);let x=Math.round(parseFloat(note.style.left)||0),y=Math.round(parseFloat(note.style.top)||0);try{await patch('mural_notes',note.dataset.muralnote,{x,y,updated_at:new Date().toISOString()});let n=(D.muralNotes||[]).find(z=>z.id===note.dataset.muralnote);if(n){n.x=x;n.y=y}}catch(err){console.warn(err)}};h.addEventListener('pointermove',move);h.addEventListener('pointerup',up);h.addEventListener('pointercancel',up)}})}
function morePage(){return`<section class="more-hub-hero"><small class="ey">CENTRAL</small><h2>Tudo que move a agência</h2><p class="muted">Clientes, crescimento, operação e gestão organizados em um só lugar.</p></section><div class="more-main-grid"><button class="more-feature primary" data-v="clients"><div class="mf-top"><span class="mf-icon">◎</span><span class="mf-arrow">→</span></div><div><small>RELACIONAMENTO</small><h3>Clientes</h3><p>Plano ativo, serviços, contratos e toda a operação de cada cliente.</p></div></button><button class="more-feature" data-v="commercial"><div class="mf-top"><span class="mf-icon">↗</span><span class="mf-arrow">→</span></div><div><small>CRESCIMENTO</small><h3>Comercial</h3><p>Prospecção, propostas, negociações e próximos follow-ups.</p></div></button><button class="more-feature" data-v="dna"><div class="mf-top"><span class="mf-icon">✦</span><span class="mf-arrow">→</span></div><div><small>NOSSA MARCA</small><h3>DNA Colab</h3><p>Conteúdo, estratégia, parcerias, campanhas e evolução da Colab.</p></div></button></div><button class="mural-entry" data-v="mural"><div class="mural-entry-copy"><small>ENTRE A GENTE</small><h3>Mural Colab</h3><p>Post-its, recados, ideias soltas e caos criativo organizado.</p></div><span class="mural-entry-go">↗</span></button><section class="more-group"><div class="more-group-title"><div><small class="ey">OPERAÇÃO</small><h3>Produção & estratégia</h3></div></div><div class="more-compact-grid"><button class="more-compact" data-v="ideas"><b><span class="mi">✦</span>Banco de ideias</b><p>Insights, referências e briefings.</p></button><button class="more-compact" data-v="production"><b><span class="mi">◉</span>StoryMaker</b><p>Briefing, captação, entregas e arquivos.</p></button><button class="more-compact" data-v="traffic"><b><span class="mi">↗</span>Tráfego</b><p>Campanhas, criativos e resultados.</p></button></div></section><section class="more-group"><div class="more-group-title"><div><small class="ey">ACERVO & FERRAMENTAS</small><h3>Nossa base criativa</h3></div></div><div class="more-compact-grid"><button class="more-compact" data-v="library"><b><span class="mi">✦</span>Biblioteca interna</b><p>Referências organizadas por cliente.</p></button><button class="more-compact" data-v="files"><b><span class="mi">▧</span>Arquivos</b><p>Banco de imagens, vídeos e materiais.</p></button><button class="more-compact" data-v="access"><b><span class="mi">♙</span>Acessos</b><p>Equipe, clientes e permissões.</p></button></div></section><section class="more-group management"><div class="more-group-title"><div><small class="ey">GESTÃO</small><h3>Números & evolução</h3></div></div><div class="more-compact-grid"><button class="more-compact" data-v="finance"><b><span class="mi">R$</span>Financeiro</b><p>Caixa, mensalidades, contratos e pagamentos.</p></button><button class="more-compact" data-v="goals"><b><span class="mi">◎</span>Metas Colab</b><p>Marcos, objetivos e crescimento da agência.</p></button></div></section>`}
function libraryPage(){let cats={visual:'Referência visual',reel_video:'Reels / vídeo',copy:'Copy',inspiration:'Inspiração',competitor:'Concorrente',trend:'Trend',other:'Outro'},refs=(D.refs||[]).filter(r=>libraryClient==='all'||r.client_id===libraryClient).filter(r=>libraryType==='all'||(libraryType==='uncategorized'?!r.category:r.category===libraryType));return`<div class="toolbar"><div><p class="muted">Referências da equipe, organizadas por cliente e tipo.</p></div><button class="btn pri" data-m="referenceNew">＋ Referência</button></div><div class="filters"><select id="libraryClient"><option value="all">Todos os clientes</option>${D.clients.map(c=>`<option value="${c.id}" ${libraryClient===c.id?'selected':''}>${E(c.name)}</option>`).join('')}</select><select id="libraryType"><option value="all">Todos os tipos</option>${Object.entries(cats).map(([v,l])=>`<option value="${v}" ${libraryType===v?'selected':''}>${l}</option>`).join('')}<option value="uncategorized" ${libraryType==='uncategorized'?'selected':''}>Sem categoria</option></select><span class="tag">${refs.length} referência${refs.length===1?'':'s'}</span></div><div class="libs">${refs.map(r=>`<article class="lib"><div class="head"><small class="ey">${E(cl(r.client_id)?.name||'COLAB')}</small><span class="tag">${E(cats[r.category]||'Sem categoria')}</span></div><h3>${E(r.title)}</h3><p>${E(r.notes||'')}</p>${r.source_url?`<a href="${E(r.source_url)}" target="_blank" rel="noopener" class="btn ghost small">Abrir referência ↗</a>`:''}</article>`).join('')||'<div class="empty">Nenhuma referência com esses filtros.</div>'}</div>`}
function trafficPage(){let reps=(D.trafficReports||[]).filter(r=>!trafficClient||r.client_id===trafficClient).slice().sort((a,b)=>String(b.period).localeCompare(String(a.period))),trafficClients=D.clients.filter(c=>(!trafficClient||c.id===trafficClient)&&D.services.some(s=>s.client_id===c.id&&s.active&&s.service==='trafego')),r=trafficClient?reps[0]:null,c=trafficClient?cl(trafficClient):null;return`<div class="toolbar"><div><p class="muted">Campanhas, investimento e resultados dos clientes de Tráfego Pago.</p></div><button class="btn pri" data-m="trafficReportNew" ${trafficClient?`data-client="${trafficClient}"`:''}>＋ Atualizar métricas</button></div><div class="filters"><select id="trafficClient"><option value="">Todos os clientes</option>${D.clients.filter(c=>c.active&&D.services.some(s=>s.client_id===c.id&&s.active&&s.service==='trafego')).map(c=>`<option value="${c.id}" ${trafficClient===c.id?'selected':''}>${E(c.name)}</option>`).join('')}</select></div>${trafficClient?`<section class="panel" style="margin-bottom:14px"><div class="head"><div><small class="ey">TRÁFEGO PAGO · ${E(c?.name||'')}</small><h3>${r?'Visão do período '+String(r.period).slice(0,7):'Primeiro relatório'}</h3><p class="muted">Investimento, campanhas e resultados em uma visão só.</p></div><button class="btn ghost small" data-m="trafficReportNew" data-client="${trafficClient}">${r?'Editar / atualizar métricas':'Adicionar métricas'}</button></div>${r?`<div class="traffic-metrics"><article class="traffic-metric"><span>Investimento</span><b>${money(r.invested)}</b></article><article class="traffic-metric"><span>${E(r.result_label||'Resultados')}</span><b>${Number(r.results||0).toLocaleString('pt-BR')}</b></article><article class="traffic-metric"><span>Custo por resultado</span><b>${money(r.cost_per_result)}</b></article><article class="traffic-metric"><span>Alcance</span><b>${Number(r.reach||0).toLocaleString('pt-BR')}</b></article><article class="traffic-metric"><span>Cliques</span><b>${Number(r.clicks||0).toLocaleString('pt-BR')}</b></article><article class="traffic-metric"><span>Impressões</span><b>${Number(r.impressions||0).toLocaleString('pt-BR')}</b></article>${Number(r.sales||0)?`<article class="traffic-metric"><span>Vendas</span><b>${Number(r.sales).toLocaleString('pt-BR')}</b></article>`:''}${Number(r.revenue||0)?`<article class="traffic-metric"><span>Faturamento atribuído</span><b>${money(r.revenue)}</b></article>`:''}</div>${r.campaign_summary?`<div style="border-top:1px solid #292929;padding-top:12px"><small class="ey">CAMPANHAS DO PERÍODO</small><p>${E(r.campaign_summary).replace(/\n/g,'<br>')}</p></div>`:''}${r.notes?`<div style="border-top:1px solid #292929;padding-top:12px"><small class="ey">LEITURA COLAB</small><p>${E(r.notes).replace(/\n/g,'<br>')}</p></div>`:''}`:'<div class="empty">Ainda não há métricas cadastradas para esta cliente.</div>'}</section>`:trafficClients.length?`<div class="service-grid">${trafficClients.map(c=>{let x=reps.find(r=>r.client_id===c.id);return`<article class="service-card" style="cursor:default"><div><span class="svc-icon">↗</span><p class="ey" style="margin-top:10px">TRÁFEGO PAGO</p><b>${E(c.name)}</b><p>${x?`${String(x.period).slice(0,7)} · ${money(x.invested)} investidos`:'Aguardando primeiro relatório'}</p></div><span class="go">${x?`${Number(x.results||0).toLocaleString('pt-BR')} ${E(x.result_label||'resultados').toLowerCase()}`:'Sem métricas ainda'}</span></article>`}).join('')}</div>`:''}<section class="panel" style="margin-top:14px"><div class="head"><div><small class="ey">RELATÓRIOS</small><h3>Histórico de resultados</h3></div></div>${reps.map(x=>`<div class="row"><span class="dot ${Number(x.results)>0?'g':''}"></span><div class="grow"><b>${E(cl(x.client_id)?.name||'')} · ${String(x.period||'').slice(0,7)}</b><small>${money(x.invested)} investidos · ${Number(x.results||0).toLocaleString('pt-BR')} ${E(x.result_label||'resultados').toLowerCase()} · ${money(x.cost_per_result)} por resultado</small></div><span class="tag">${Number(x.impressions||0).toLocaleString('pt-BR')} impr.</span></div>`).join('')||'<div class="empty">Nenhum relatório de tráfego cadastrado.</div>'}</section><section class="panel" style="margin-top:14px"><div class="head"><div><small class="ey">CRIATIVOS</small><h3>Campanhas e hipóteses</h3></div><button class="btn ghost small" data-m="creativeNew" ${trafficClient?`data-client="${trafficClient}"`:''}>＋ Criativo</button></div>${D.creatives.filter(x=>!trafficClient||x.client_id===trafficClient).map(x=>`<div class="row"><span class="dot ${x.status==='active'?'g':''}"></span><div class="grow"><b>${E(x.name)}</b><small>${E(cl(x.client_id)?.name||'')} · ${E(x.campaign_name||'Sem campanha')}</small></div><span class="tag">${E(x.status)}</span></div>`).join('')||'<div class="empty">Nenhum criativo.</div>'}</section>`}
function identityResourceLabel(v){return({brand_book:'Brand Book',logo:'Logos',palette:'Paleta',fonts:'Fontes',canva:'Canva editável',drive:'Pasta no Drive',other:'Outro'})[v]||v}
function identityTeamPage(){let cid=filesClient||D.clients.find(c=>c.active)?.id||'',c=cl(cid),rs=(D.identityResources||[]).filter(r=>r.client_id===cid);return`<div class="toolbar"><div><p class="muted">Brand Book, logos, paleta e materiais finais da identidade.</p></div><button class="btn pri" data-m="identityResourceNew" data-client="${cid}">＋ Adicionar material</button></div><div class="filters"><select id="identityClient">${D.clients.filter(c=>c.active).map(c=>`<option value="${c.id}" ${c.id===cid?'selected':''}>${E(c.name)}</option>`).join('')}</select></div><section class="hero module-hero"><div><small class="ey">IDENTIDADE VISUAL</small><h2>${E(c?.name||'Cliente')}</h2><p class="muted">Toda a identidade organizada por links, sem pesar o aplicativo.</p></div><button class="btn ghost" data-identityfiles="${cid}">Arquivos leves</button></section><section class="panel" style="margin-top:14px"><div class="head"><div><small class="ey">MATERIAIS DA MARCA</small><h3>Links e arquivos finais</h3></div><span class="tag">${rs.length} itens</span></div>${rs.map(x=>`<div class="row"><span class="dot"></span><div class="grow"><b>${E(x.title)}</b><small>${E(identityResourceLabel(x.resource_type))}${x.notes?' · '+E(x.notes):''}</small></div><div class="actions"><a class="btn ghost small" href="${E(x.url)}" target="_blank" rel="noopener">Abrir ↗</a><button class="btn danger small" data-identitydelete="${x.id}">Excluir</button></div></div>`).join('')||'<div class="empty">Adicione Brand Book, logos, paleta, pasta do Drive ou links do Canva.</div>'}</section>`}
