 if(t==='clientNew'){let name=String(f.get('name')).trim(),slug=name.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-')+'-'+Date.now().toString().slice(-4),r=await api('/rest/v1/clients',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({organization_id:org,name,slug,segment:f.get('segment')||null,initials:ini(name),objective:f.get('objective')||null})});for(const s of f.getAll('services'))await api('/rest/v1/client_services',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({organization_id:org,client_id:r[0].id,service:s,active:true})})}
 if(t==='contentNew'){let cid=f.get('client_id'),pm=f.get('plan_month')||contentMonth,plan=await ensurePlan(cid,pm),r=await api('/rest/v1/contents',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({organization_id:org,client_id:cid,title:f.get('title'),format:f.get('format'),objective:f.get('objective')||null,script:f.get('script')||null,caption:f.get('caption')||null,cta:f.get('cta')||null,external_media_url:f.get('external_media_url')||null,editorial_pillar_id:f.get('editorial_pillar_id')||null,monthly_plan_id:plan?.id||null,publication_date:f.get('publication_date')||null,status:f.get('status'),created_by:uid})});await ensureTeamWorkflow(r[0]);let files=f.getAll('content_files').filter(x=>x&&x.size);if(files.length)await uploadFilesForContent(r[0],files);if(f.get('status')==='approval')await createApproval(r[0].id,cid)}
 if(t==='trafficReportNew'){let cid=f.get('client_id'),period=(f.get('period')||monthNow())+'-01',invested=Number(f.get('invested')||0),results=Number(f.get('results')||0),cpr=Number(f.get('cost_per_result')||0)||(results?invested/results:0);await api('/rest/v1/traffic_reports?on_conflict=client_id,period',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({organization_id:org,client_id:cid,period,invested,impressions:Number(f.get('impressions')||0),reach:Number(f.get('reach')||0),clicks:Number(f.get('clicks')||0),results,result_label:f.get('result_label')||'Resultados',cost_per_result:cpr,sales:Number(f.get('sales')||0),revenue:Number(f.get('revenue')||0),campaign_summary:f.get('campaign_summary')||null,notes:f.get('notes')||null,created_by:uid,updated_at:new Date().toISOString()})})}
