async function convertOpportunity(id){let o=(D.opportunities||[]).find(x=>x.id===id);if(!o||o.converted_client_id)return;try{let slug=String(o.name||'cliente').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')+'-'+String(Date.now()).slice(-5),r=await api('/rest/v1/clients',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({organization_id:M.organization_id,name:o.name,slug,segment:o.segment||'Cliente Colab',initials:ini(o.name),active:true,objective:o.notes||null})}),cid=r[0].id;let svcs=o.service_interest==='complete'?['social_media','storymaker','trafego']:['social_media','storymaker','trafego','identidade_visual'].includes(o.service_interest)?[o.service_interest]:[];for(const service of svcs)await api('/rest/v1/client_services',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({organization_id:M.organization_id,client_id:cid,service,active:true})});await patch('sales_opportunities',id,{stage:'won',converted_client_id:cid,updated_at:new Date().toISOString()});await load();V='clients';MD={type:'clientDetail',id:cid};render();toast('Oportunidade transformada em cliente 🧡')}catch(x){toast(x.message)}}
