async function markRecurringCostPaid(id){let x=(D.recurringCosts||[]).find(v=>v.id===id);if(!x)return;try{let paid=new Date().toISOString();await api('/rest/v1/expenses',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({organization_id:M.organization_id,description:x.name,category:'fixed',expense_date:today(),due_date:x.next_due_date,amount:Number(x.amount||0),status:'paid',paid_at:paid,vendor:x.vendor||null,notes:x.notes||null,created_by:S.user?.id})});let d=new Date(x.next_due_date+'T12:00:00');if(x.recurrence==='monthly')d.setMonth(d.getMonth()+1);if(x.recurrence==='annual')d.setFullYear(d.getFullYear()+1);let next=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');await patch('recurring_costs',id,{last_paid_at:paid,next_due_date:x.recurrence==='one_time'?x.next_due_date:next,status:x.recurrence==='one_time'?'inactive':'active',updated_at:paid});await load();render();toast('Conta marcada como paga')}catch(e){toast(e.message)}}
