function encPath(p){return p.split('/').map(encodeURIComponent).join('/')}
async function uploadRaw(file,path){let h={apikey:K,Authorization:'Bearer '+S.access_token,'Content-Type':file.type||'application/octet-stream','x-upsert':'false'},r=await tf(B+'/storage/v1/object/client-media/'+encPath(path),{method:'POST',headers:h,body:file},300000);if(!r.ok)throw Error(await r.text())}
async function uploadFilesForContent(c,files){let v=Number(c.current_version||1),hasPrimary=(D.assets||[]).some(a=>a.content_id===c.id&&Number(a.version_no||1)===v&&a.is_primary);for(let i=0;i<files.length;i++){let f=files[i],name=Date.now()+'-'+i+'-'+f.name.replace(/[^a-zA-Z0-9._-]/g,'-'),path=`${M.organization_id}/${c.client_id}/contents/${c.id}/v${v}/${name}`;await uploadRaw(f,path);await api('/rest/v1/content_assets',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({organization_id:M.organization_id,client_id:c.client_id,content_id:c.id,storage_path:path,file_name:f.name,mime_type:f.type||null,file_size:f.size,asset_type:f.type.startsWith('video/')?'video':f.type.startsWith('image/')?'image':'file',version_no:v,is_primary:!hasPrimary&&i===0,uploaded_by:S.user?.id})})}}async function uploadContentFiles(e){let files=[...e.target.files],c=D.contents.find(x=>x.id===MD.id);try{await uploadFilesForContent(c,files);await load();render();toast('Arquivos anexados')}catch(x){toast(x.message)}}
async function uploadInsightFile(insightId,cid,f){let name=Date.now()+'-'+f.name.replace(/[^a-zA-Z0-9._-]/g,'-'),path=`${M.organization_id}/${cid}/insights/${insightId}/${name}`;await uploadRaw(f,path);await api('/rest/v1/client_insight_assets',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({organization_id:M.organization_id,client_id:cid,insight_id:insightId,storage_path:path,file_name:f.name,mime_type:f.type||null,file_size:f.size,uploaded_by:S.user?.id})})}
async function uploadBank(e){let cid=M.role==='client'?M.client_id:filesClient,files=[...e.target.files];try{for(const f of files){let name=Date.now()+'-'+f.name.replace(/[^a-zA-Z0-9._-]/g,'-'),path=`${M.organization_id}/${cid}/bank/${name}`;await uploadRaw(f,path)}toast('Arquivos enviados');e.target.value='';loadBank()}catch(x){toast(x.message)}}
async function loadBank(){let cid=M.role==='client'?M.client_id:filesClient,a=document.getElementById('bankArea');if(!cid||!a)return;try{let p=`${M.organization_id}/${cid}/bank`,x=await api('/storage/v1/object/list/client-media',{method:'POST',body:JSON.stringify({prefix:p,limit:100,offset:0,sortBy:{column:'created_at',order:'desc'}})});a.innerHTML=x.length?x.filter(f=>f.name!=='.emptyFolderPlaceholder').map(f=>`<article class="file"><div class="preview">${/\.(mp4|mov|webm)$/i.test(f.name)?'▶':'▧'}</div><b>${E(f.name)}</b><button class="btn ghost small" data-file="${E(p+'/'+f.name)}">Abrir</button></article>`).join(''):'<div class="empty">Nenhum arquivo ainda.</div>';a.querySelectorAll('[data-file]').forEach(b=>b.onclick=()=>openFile(b.dataset.file))}catch(x){a.innerHTML='<div class="empty">'+E(x.message)+'</div>'}}
async function signed(path){let x=await api('/storage/v1/object/sign/client-media/'+encPath(path),{method:'POST',body:JSON.stringify({expiresIn:900})}),u=x.signedURL||x.signedUrl;if(u&&u.startsWith('/'))u=B+'/storage/v1'+u;return u}
async function openFile(path){try{window.open(await signed(path),'_blank')}catch(x){toast(x.message)}}
async function hydratePreviews(){for(const el of document.querySelectorAll('[data-asset-path]')){if(el.dataset.done)continue;el.dataset.done='1';try{let u=await signed(el.dataset.assetPath),mime=el.dataset.mime||'';el.innerHTML=mime.startsWith('video/')?(el.dataset.thumb?`<video muted playsinline preload="metadata" src="${E(u)}#t=0.1"></video>`:`<video controls playsinline preload="metadata" src="${E(u)}"></video>`):mime.startsWith('image/')?`<img src="${E(u)}" alt="${E(el.dataset.filename||'Prévia')}">`:`<span>▧</span>`}catch{el.innerHTML='▧'}}}

function ideaTypeLabel(v){return({idea:'Ideia',reference:'Referência',reel_reference:'Reels / vídeo',insight:'Insight',trend:'Trend'})[v]||v}
function ideaStageOf(i){if(i.status!=='converted'||!i.converted_content_id)return'idea';let c=(D.contents||[]).find(x=>x.id===i.converted_content_id);if(!c)return'idea';return['scheduled','published'].includes(c.status)?'used':'creating'}
function ideaStageLabel(v){return({idea:'Banco de ideias',creating:'Em criação',used:'Já utilizado'})[v]||v}
function ideasPage(){let all=D.insights||[],base=all.filter(i=>ideasClient==='all'||i.client_id===ideasClient),shown=base.filter(i=>(ideasStage==='all'||ideaStageOf(i)===ideasStage)&&(ideasType==='all'||i.insight_type===ideasType)),creating=base.filter(i=>ideaStageOf(i)==='creating').length,used=base.filter(i=>ideaStageOf(i)==='used').length,refs=base.filter(i=>['reference','reel_reference','trend'].includes(i.insight_type)).length;return`<div class="toolbar"><div><p class="muted">A memória criativa de cada cliente: ideias, referências e conteúdos que nasceram daqui.</p></div><button class="btn pri" data-m="insightNewTeam">＋ Nova ideia</button></div><div class="filters"><select id="ideasClient"><option value="all">Todos os clientes</option>${D.clients.filter(c=>c.active).map(c=>`<option value="${c.id}" ${ideasClient===c.id?'selected':''}>${E(c.name)}</option>`).join('')}</select><select id="ideasStage"><option value="all" ${ideasStage==='all'?'selected':''}>Todas as etapas</option><option value="idea" ${ideasStage==='idea'?'selected':''}>Banco de ideias</option><option value="creating" ${ideasStage==='creating'?'selected':''}>Em criação</option><option value="used" ${ideasStage==='used'?'selected':''}>Já utilizados</option></select><select id="ideasType"><option value="all">Todos os tipos</option><option value="idea" ${ideasType==='idea'?'selected':''}>Ideias</option><option value="reference" ${ideasType==='reference'?'selected':''}>Referências</option><option value="reel_reference" ${ideasType==='reel_reference'?'selected':''}>Reels / vídeos</option><option value="insight" ${ideasType==='insight'?'selected':''}>Insights</option><option value="trend" ${ideasType==='trend'?'selected':''}>Trends</option></select></div><div class="stats"><article class="stat"><span>No banco</span><b>${base.filter(i=>ideaStageOf(i)==='idea').length}</b><small>ideias disponíveis</small></article><article class="stat"><span>Em criação</span><b>${creating}</b><small>virando conteúdo</small></article><article class="stat"><span>Já utilizados</span><b>${used}</b><small>histórico criativo</small></article><article class="stat"><span>Referências</span><b>${refs}</b><small>links, Reels e trends</small></article></div><section class="panel"><div class="head"><div><small class="ey">BANCO DE IDEIAS</small><h3>${ideasClient==='all'?'Todos os clientes':E(cl(ideasClient)?.name||'Cliente')}</h3></div><span class="tag">${shown.length} itens</span></div><div class="grid2">${shown.map(i=>ideaCard(i,true)).join('')||'<div class="empty">Nenhuma ideia com esses filtros.</div>'}</div></section><section class="panel" style="margin-top:14px"><div class="head"><div><small class="ey">BRIEFINGS MENSAIS</small><h3>Matéria-prima do planejamento</h3></div></div>${(D.briefings||[]).filter(b=>ideasClient==='all'||b.client_id===ideasClient).slice(0,8).map(b=>`<div class="row"><span class="dot ${b.status==='submitted'?'g':''}"></span><div class="grow"><b>${E(cl(b.client_id)?.name||'')}</b><small>${new Date(b.month+'T12:00:00').toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</small></div><button class="btn ghost small" data-briefopen="${b.id}">Abrir briefing</button></div>`).join('')||'<div class="empty">Nenhum briefing para este filtro.</div>'}</section>`}
function ideaCard(i,team=false){let a=(D.insightAssets||[]).filter(x=>x.insight_id===i.id),stage=ideaStageOf(i),c=i.converted_content_id?(D.contents||[]).find(x=>x.id===i.converted_content_id):null,stageCls=stage==='used'?'g':stage==='creating'?'y':'o';return`<article class="idea ${stage==='idea'?'new':''}" style="margin:8px 0"><div class="head"><div><small class="ey">${E(cl(i.client_id)?.name||'')}</small><h3>${E(i.title)}</h3></div><span class="tag ${stageCls}">${E(ideaStageLabel(stage))}</span></div><div class="chips" style="margin-bottom:8px"><span class="tag">${E(ideaTypeLabel(i.insight_type))}</span>${c?`<span class="tag">${E(fmt(c.format))} · ${E(cs(c.status))}</span>`:''}</div><p>${E(i.notes||'')}</p><div class="chips">${i.source_url?`<a class="btn ghost small" href="${E(i.source_url)}" target="_blank" rel="noopener">Abrir referência ↗</a>`:''}${a.map(x=>`<button class="btn ghost small" data-file="${E(x.storage_path)}">${E(x.file_name)}</button>`).join('')}${team&&stage==='idea'?`<button class="btn pri small" data-convert="${i.id}">Transformar em conteúdo</button>`:''}${team&&c?`<button class="btn ghost small" data-contentfromidea="${c.id}">Abrir conteúdo →</button>`:''}</div></article>`}
async function convertInsight(id){let i=D.insights.find(x=>x.id===id);try{let plan=await ensurePlan(i.client_id,contentMonth),r=await api('/rest/v1/contents',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({organization_id:M.organization_id,client_id:i.client_id,title:i.title,format:i.insight_type==='reel_reference'?'reel':'reel',objective:i.notes||null,internal_notes:i.source_url?'Referência: '+i.source_url:null,monthly_plan_id:plan.id,status:'idea',created_by:S.user?.id})});let c=r[0];await api('/rest/v1/content_team_workflow',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({organization_id:M.organization_id,client_id:i.client_id,content_id:c.id,source_insight_id:i.id,internal_status:'draft',internal_notes:'Conteúdo criado a partir do Banco de Ideias.',created_by:S.user?.id})});await patch('client_insights',id,{status:'converted',converted_content_id:c.id,updated_at:new Date().toISOString()});contentClient=i.client_id;contentMode='list';V='content';await load();MD={type:'contentDetail',id:c.id};render();toast('Ideia transformada em conteúdo ✨')}catch(x){toast(x.message)}}
async function saveContentEdit(e){e.preventDefault();let f=new FormData(e.currentTarget),c=D.contents.find(x=>x.id===MD.id);try{let status=f.get('status');await patch('contents',c.id,{title:f.get('title'),objective:f.get('objective')||null,script:f.get('script')||null,caption:f.get('caption')||null,cta:f.get('cta')||null,external_media_url:f.get('external_media_url')||null,publication_date:f.get('publication_date')||null,status,updated_at:new Date().toISOString()});let old=(D.teamWorkflow||[]).find(w=>w.content_id===c.id),payload={organization_id:M.organization_id,client_id:c.client_id,content_id:c.id,canva_edit_url:f.get('canva_edit_url')||null,internal_status:f.get('internal_status')||'draft',assigned_to:f.get('internal_assigned_to')||null,internal_notes:f.get('workflow_internal_notes')||null,updated_at:new Date().toISOString()};if(old)await patch('content_team_workflow',old.id,payload);else await api('/rest/v1/content_team_workflow',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({...payload,created_by:S.user?.id})});if(status==='approval'&&!D.approvals.some(a=>a.content_id===c.id&&a.status==='pending'))await createApproval(c.id,c.client_id);await load();render();toast('Conteúdo e criação interna atualizados')}catch(x){toast(x.message)}}

async function ensureTeamWorkflow(c){let old=(D.teamWorkflow||[]).find(w=>w.content_id===c.id);if(old)return old;let r=await api('/rest/v1/content_team_workflow',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({organization_id:M.organization_id,client_id:c.client_id,content_id:c.id,internal_status:'draft',created_by:S.user?.id})});return r[0]}
async function updateWorkflowStatus(contentId,status){let c=D.contents.find(x=>x.id===contentId);try{let w=(D.teamWorkflow||[]).find(x=>x.content_id===contentId);if(w)await patch('content_team_workflow',w.id,{internal_status:status,updated_at:new Date().toISOString()});else await api('/rest/v1/content_team_workflow',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({organization_id:M.organization_id,client_id:c.client_id,content_id:c.id,internal_status:status,created_by:S.user?.id})});await load();render();toast('Etapa da criação atualizada')}catch(x){toast(x.message)}}
function creationBoard(items){let stages=[['draft','Rascunho'],['design','Em design'],['internal_review','Revisão interna'],['internal_approved','Aprovado internamente']];return`<div class="kan creation-kan">${stages.map(([v,l])=>{let rows=items.filter(c=>((D.teamWorkflow||[]).find(w=>w.content_id===c.id)?.internal_status||'draft')===v);return`<section class="col"><div class="head"><b>${l}</b><span class="tag">${rows.length}</span></div>${rows.map(c=>{let w=(D.teamWorkflow||[]).find(x=>x.content_id===c.id),owner=w?.assigned_to?profile(w.assigned_to)?.display_name:'Equipe';return`<article class="task" data-contentopen="${c.id}"><small class="ey">${E(fmt(c.format))}</small><b>${E(c.title)}</b><small class="muted">${E(owner||'Equipe')} · ${E(cl(c.client_id)?.name||'')}</small>${w?.canva_edit_url?`<a class="btn ghost small" href="${E(w.canva_edit_url)}" target="_blank" rel="noopener" style="margin-top:8px" data-stop>Canva ↗</a>`:'<small class="muted" style="display:block;margin-top:8px">Canva ainda não vinculado</small>'}<select data-workstatus="${c.id}" style="margin-top:8px">${stages.map(([sv,sl])=>`<option value="${sv}" ${sv===v?'selected':''}>${sl}</option>`).join('')}</select></article>`}).join('')||'<div class="empty">Nada aqui.</div>'}</section>`}).join('')}</div>`}
function chatUnread(){let reads=new Set((D.chatReads||[]).map(x=>x.message_id));return(D.chatMessages||[]).filter(x=>x.sender_id!==S.user?.id&&!reads.has(x.id)).length}
function chatDock(){let msgs=(D.chatMessages||[]).slice(-80),unread=chatUnread();return`${CHATOPEN?`<section class="chat-panel"><div class="chat-head"><div><h3>Chat</h3></div><button id="chatClose" type="button" aria-label="Fechar">×</button></div><div class="chat-messages" id="chatMessages">${msgs.map(m=>`<div class="chat-msg ${m.sender_id===S.user?.id?'me':''}"><b>${E(profile(m.sender_id)?.display_name||'Equipe')}</b><p>${E(m.body)}</p><small>${notificationWhen(m.created_at)}</small></div>`).join('')||'<div class="chat-empty">Ainda não tem conversa por aqui.<br>Começa com um “amiga…” 😂</div>'}</div><form id="chatForm" class="chat-form"><input id="chatInput" name="body" maxlength="500" autocomplete="off" placeholder="Escreve pra equipe..." required><button>Enviar</button></form></section>`:''}<button id="chatToggle" class="chat-fab" type="button" aria-label="Chat Colab">✦${unread?`<span class="chat-badge">${unread>99?'99+':unread}</span>`:''}</button>`}
function toggleChat(){CHATOPEN=!CHATOPEN;render();if(CHATOPEN)setTimeout(markChatRead,80)}
async function sendChat(e){e.preventDefault();let f=new FormData(e.currentTarget),body=String(f.get('body')||'').trim();if(!body)return;try{await api('/rest/v1/team_chat_messages',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({organization_id:M.organization_id,sender_id:S.user.id,body})});await refreshChatData(true)}catch(x){toast(x.message)}}
async function markChatRead(){let unread=(D.chatMessages||[]).filter(x=>x.sender_id!==S.user?.id&&!new Set((D.chatReads||[]).map(r=>r.message_id)).has(x.id));if(!unread.length)return;try{await api('/rest/v1/team_chat_reads?on_conflict=message_id,user_id',{method:'POST',headers:{Prefer:'resolution=ignore-duplicates,return=minimal'},body:JSON.stringify(unread.map(x=>({message_id:x.id,user_id:S.user.id})))});D.chatReads=[...(D.chatReads||[]),...unread.map(x=>({message_id:x.id,user_id:S.user.id}))];let b=document.querySelector('.chat-badge');if(b)b.remove()}catch(e){console.warn('chat read',e)}}
async function refreshChatData(forceRender=false){if(M?.role!=='team'||!S?.user?.id)return;try{let a=await Promise.all([api('/rest/v1/team_chat_messages?select=*&order=created_at.asc&limit=120'),api('/rest/v1/team_chat_reads?select=*&user_id=eq.'+S.user.id)]),before=(D.chatMessages||[]).length;D.chatMessages=a[0]||[];D.chatReads=a[1]||[];if(forceRender||CHATOPEN||D.chatMessages.length!==before)render()}catch(e){console.warn('chat',e)}}
setInterval(()=>{if(M?.role==='team'&&S)refreshNotificationData()},30000);
setInterval(()=>{if(M?.role==='team'&&S)refreshChatData(false)},10000);

/* CONTRACT_TYPES_PATCH_20260823 */
const _contractModalBase=modal;
modal=function(){
 if(MD?.type==='contractNew'){
  const clientOptions=`<option value="">Contato avulso / sem cadastro</option>${D.clients.filter(c=>c.active).map(c=>`<option value="${c.id}">${E(c.name)}</option>`).join('')}`;
  return `<div class="modalbg"><div class="modal wide"><div class="head"><div><small class="ey">CONTRATO</small><h2>Novo contrato</h2><p class="muted">Escolha se esta contratação é mensal ou avulsa.</p></div><button class="btn ghost small" type="button" data-close>✕</button></div><form id="mf" data-type="contractNew">
  <div class="field"><label>Tipo de contratação</label><div class="contractTypeSwitch"><label><input type="radio" name="contract_type" value="monthly" checked> Mensal / recorrente</label><label><input type="radio" name="contract_type" value="one_off"> Avulso / uma vez</label></div></div>
  <div class="formgrid"><div class="field"><label>Cliente</label><select name="client_id" id="contractClient">${clientOptions}</select></div><div class="field" id="externalContactField"><label>Nome do contato avulso</label><input name="external_contact_name" placeholder="Ex.: Elias & Karol"></div></div>
  <div class="field"><label>Serviço</label><select name="service"><option value="social_media">Social Media</option><option value="storymaker">StoryMaker</option><option value="trafego">Tráfego Pago</option><option value="identidade_visual">Identidade Visual</option><option value="outro">Outro</option></select></div>
  <div id="monthlyContractFields"><div class="formgrid"><div class="field"><label>Início</label><input name="start_date" type="date"></div><div class="field"><label>Fim</label><input name="end_date" type="date"></div></div><div class="formgrid"><div class="field"><label>Mensalidade</label><input name="monthly_fee" type="number" step="0.01" min="0"></div><div class="field"><label>Dia do pagamento</label><input name="billing_day" type="number" min="1" max="31" value="5"></div></div></div>
  <div id="oneOffContractFields" style="display:none"><div class="formgrid"><div class="field"><label>Data do serviço</label><input name="service_date" type="date"></div><div class="field"><label>Valor total</label><input name="total_amount" type="number" step="0.01" min="0"></div></div><div class="field"><label>Forma de cobrança</label><div class="contractTypeSwitch"><label><input type="radio" name="billing_mode" value="cash" checked> À vista</label><label><input type="radio" name="billing_mode" value="installments"> Parcelado</label></div></div><div class="formgrid"><div class="field"><label id="firstDueLabel">Vencimento</label><input name="first_due_date" type="date"></div><div class="field" id="installmentCountField" style="display:none"><label>Número de parcelas</label><input name="installment_count" type="number" min="2" max="24" value="2"></div></div></div>
  <div class="field"><label>Forma de pagamento</label><input name="payment_method" placeholder="Pix, boleto, cartão..."></div>
  <div class="field"><label>Resumo do serviço / contrato</label><textarea name="package_summary" rows="3" placeholder="O que foi contratado?"></textarea></div>
  <div class="field"><label>Entregáveis — um por linha</label><textarea name="deliverables" rows="4" placeholder="Cobertura de 6h\nStories em tempo real\n1 Reels"></textarea></div>
  <button class="btn pri full">Salvar contrato</button></form></div></div>`;
 }
 return _contractModalBase();
};
function contractServiceLabel(v){return({social_media:'Social Media',storymaker:'StoryMaker',trafego:'Tráfego Pago',identidade_visual:'Identidade Visual',outro:'Outro'})[v]||v||'Serviço'}
function toggleContractForm(){
 const form=document.getElementById('mf');if(!form||form.dataset.type!=='contractNew')return;
 const type=form.querySelector('input[name="contract_type"]:checked')?.value||'monthly';
 const one=type==='one_off';
 const m=document.getElementById('monthlyContractFields'),o=document.getElementById('oneOffContractFields');if(m)m.style.display=one?'none':'block';if(o)o.style.display=one?'block':'none';
 const cid=document.getElementById('contractClient')?.value||'';const ef=document.getElementById('externalContactField');if(ef)ef.style.display=cid?'none':'block';
 const bm=form.querySelector('input[name="billing_mode"]:checked')?.value||'cash';const ic=document.getElementById('installmentCountField'),lbl=document.getElementById('firstDueLabel');if(ic)ic.style.display=one&&bm==='installments'?'block':'none';if(lbl)lbl.textContent=bm==='installments'?'Vencimento da 1ª parcela':'Vencimento';
}
const _contractBindBase=bind;
bind=function(){_contractBindBase();const f=document.getElementById('mf');if(f?.dataset.type==='contractNew'){f.querySelectorAll('input[name="contract_type"],input[name="billing_mode"]').forEach(x=>x.addEventListener('change',toggleContractForm));document.getElementById('contractClient')?.addEventListener('change',toggleContractForm);toggleContractForm()}};
function isoAddMonths(dateStr,n){const d=new Date(dateStr+'T12:00:00'),day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+n);const last=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();d.setDate(Math.min(day,last));return d.toISOString().slice(0,10)}
async function saveNewContract(form){
 const f=new FormData(form),org=M.organization_id,uid=S.user?.id,type=f.get('contract_type')||'monthly',clientId=f.get('client_id')||null,external=String(f.get('external_contact_name')||'').trim()||null,service=f.get('service')||'outro',summary=f.get('package_summary')||null,payment=f.get('payment_method')||null;
 if(type==='monthly'&&!clientId)throw Error('Contrato mensal precisa estar vinculado a um cliente cadastrado.');
 if(type==='one_off'&&!clientId&&!external)throw Error('Informe o cliente ou o nome do contato avulso.');
 let payload={organization_id:org,client_id:clientId,external_contact_name:external,contract_type:type,service,title:type==='monthly'?'Contrato mensal':'Serviço avulso',payment_method:payment,package_summary:summary,status:'active',created_by:uid};
 if(type==='monthly'){
  const start=f.get('start_date'),end=f.get('end_date'),fee=Number(f.get('monthly_fee')||0),day=Number(f.get('billing_day')||5);if(!start||!end)throw Error('Informe início e fim do contrato.');if(fee<=0)throw Error('Informe a mensalidade.');Object.assign(payload,{start_date:start,end_date:end,monthly_fee:fee,billing_day:day,total_amount:null,billing_mode:'monthly',installment_count:null,first_due_date:null,service_date:null});
 }else{
  const serviceDate=f.get('service_date')||null,total=Number(f.get('total_amount')||0),billing=f.get('billing_mode')||'cash',firstDue=f.get('first_due_date')||serviceDate,count=billing==='installments'?Math.max(2,Number(f.get('installment_count')||2)):1;if(total<=0)throw Error('Informe o valor total do serviço.');if(!firstDue)throw Error('Informe o vencimento.');Object.assign(payload,{start_date:serviceDate,end_date:serviceDate,service_date:serviceDate,monthly_fee:0,billing_day:5,total_amount:total,billing_mode:billing,installment_count:count,first_due_date:firstDue});
 }
 const r=await api('/rest/v1/client_contracts',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify(payload)}),contract=r[0];
 const lines=String(f.get('deliverables')||'').split('\n').map(x=>x.trim()).filter(Boolean);for(const line of lines)await api('/rest/v1/contract_items',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({organization_id:org,contract_id:contract.id,item_name:line})});
 if(type==='one_off'){
  const totalCents=Math.round(Number(payload.total_amount)*100),count=payload.installment_count||1,base=Math.floor(totalCents/count),rem=totalCents-base*count;
  for(let i=0;i<count;i++){const due=isoAddMonths(payload.first_due_date,i),cents=base+(i===count-1?rem:0),desc=count>1?`${contractServiceLabel(service)} — parcela ${i+1}/${count}`:contractServiceLabel(service);await api('/rest/v1/receivables',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({organization_id:org,client_id:clientId,external_contact_name:external,contract_id:contract.id,description:desc,category:'service_one_off',competence_month:due.slice(0,7)+'-01',due_date:due,amount:cents/100,status:'pending',payment_method:payment,created_by:uid})})}
 }
 await load();MD=null;render();toast(type==='monthly'?'Contrato mensal criado':'Contrato avulso criado e financeiro gerado');
}
const _contractSubmitBase=submit;
submit=async function(e){if(e.currentTarget?.dataset?.type==='contractNew'){e.preventDefault();const btn=e.currentTarget.querySelector('button:not([type=button])');const old=btn?.textContent;try{if(btn){btn.disabled=true;btn.textContent='Salvando...'}await saveNewContract(e.currentTarget)}catch(x){toast(x.message)}finally{if(btn){btn.disabled=false;btn.textContent=old}}return}_contractSubmitBase(e)};
const _contractCardBase=contractCard;
contractCard=function(c){if((c.contract_type||'monthly')==='one_off'){const who=cl(c.client_id)?.name||c.external_contact_name||'Contato avulso',parts=Number(c.installment_count||1);return `<article class="finance-card"><small class="ey">${E(who)} · AVULSO</small><h3>${money(c.total_amount||0)}</h3><p class="muted">${E(contractServiceLabel(c.service))}${c.service_date?' · '+fmtDate(c.service_date):''}</p><div class="chips"><span class="tag">${c.billing_mode==='installments'?parts+'x parcelado':'À vista'}</span>${c.payment_method?`<span class="tag">${E(c.payment_method)}</span>`:''}</div><p class="muted">${E(c.package_summary||'Serviço avulso.')}</p></article>`}return _contractCardBase(c)};


